  CODE_BLOCK_TRUNCATE_DEFAULT_COLUMNS,
  codeBlockFontPx,
  codeBlockGrows,
  codeBlockWidthPx,
  type CodeBlockLanguage,
  type CodeBlockLines,
  type CodeBlockLook,
  type CodeBlockOverflow,
  type CodeBlockSize,
