import { CodeBlockRows, pruneExpandedPaths, rowIdentity } from "./codeBlockRows";
import { FieldGesture } from "./fieldGesture";

export interface CodeBlockProps {
  /** The document. The block follows it whenever nobody is editing. */
  value: string;
  /** Write, per keystroke — the block's one write policy (see `fieldGesture.ts` for why `live` is the only mode offered here). */
  onWrite(value: string): void;
  /** Open one undo step so an edit is one Ctrl+Z, not one per character. */
  beginEdit?(): void;
  /** The commit boundary — one call per gesture, however the block was left. */
  onEditEnd?(value: string, startValue: string): void;
  /**
   * What makes this block know its grammar: slot decorations, a completion
   * source, a raw extension. Omit it and you get the plain code text box.
   */
  grammar?: CodeBlockGrammar;
  /**
   * Which of the two looks this block wears — `block` (the canvas Code
   * block: gutter, many lines, a surface's padding) or `field` (the compact
   * one-line box a Port label sits in). A look is a PRESET over
   * `lineNumbers`/`lines`/the four paddings (`codeBlock.presets.ts`); any of
   * those passed explicitly wins over the look, override-beats-preset.
   */
  look?: CodeBlockLook;
  /** The base parser. Defaults to Python; every look shares it. */
  language?: CodeBlockLanguage;
  size?: CodeBlockSize;
  /** Font-size in px when `size === "custom"`; ignored otherwise. */
  sizePx?: number;
  /** Line-number gutter. Governed by `look` when omitted. */
  lineNumbers?: boolean;
  /**
   * `single`: one line — a typed or pasted newline is dropped rather than
   * growing the box. `multi`: a lane/document — Enter inserts a line,
   * Alt+↑/↓ move one, Tab indents, and Ctrl/Cmd+Enter is the exit that
   * Enter is for a single line. Governed by `look` when omitted.
   */
  lines?: CodeBlockLines;
  /**
   * What a line wider than the box does: `clip` at the edge (an input),
   * `wrap` onto new lines, `scroll` behind a bar, or `grow` the box to fit
   * the text (`columns` is then ignored — the text decides). Governed by
   * `look` when omitted: block → scroll, field → clip.
   */
  overflow?: CodeBlockOverflow;
  /**
   * Paint every semantic UNIT as one row: the newlines inside a unit (a
   * multi-line default value inside one port line) become small `⏎`
   * glyphs, the source stays byte-identical, and the gutter counts units.
   * Units come from `grammar.units`, else Python's continuation rule
   * (`codeBlockUnits.ts`). The caret's own unit stays flat while editing;
   * the ⤢ larger view is where the real lines live. See
   * `codeBlockFlatten.ts`. Off by default.
   */
  flatten?: boolean;
  /**
   * Characters across. `> 0` fixes the box's width to that many mono cells
   * plus padding (and the gutter when line numbers are on) — see
   * `codeBlockWidthPx`; `0` (the default) fills whatever the host gives.
   */
  columns?: number;
  /**
   * Show a ⤢ button in the top-right corner. The block only ASKS to expand
   * (`onExpand`) — what a "larger view" is (a modal, a side panel, a bigger
   * shape) is the host's, since the core owns no overlay and no z-index.
   */
  expandable?: boolean;
  onExpand?(): void;
  paddingTop?: number;
  paddingBot?: number;
  paddingLeft?: number;
  paddingRight?: number;
  /**
   * Whether the document is currently editable — HOST-OWNED, like
   * TextBox's. Defaults to `true`: a bare CodeBlock is a live document you
   * click into, like an `<input>` (what a Port label and an inspector row
   * want). A host that runs its own editing session over a canvas (a shape
   * that must still drag/select at rest) passes `false` until the person
   * enters the block, then `true`. While `false` the block does NOT stop
   * pointer events (so the host's own drag/select reaches it) and does not
   * carry the `bbox-interactive` marker; while `true` it does both, so a
   * React Flow / tldraw host leaves the caret alone. Leaving editing blurs
   * the document and commits the gesture; entering it takes focus.
   */
  editing?: boolean;
  /** A read-only document: no caret, no edits, dimmed. Independent of `editing`. */
  disabled?: boolean;
  placeholder?: string;
  ariaLabel?: string;
  ariaDescribedBy?: string;
  ariaInvalid?: boolean;
  className?: string;
  testId?: string;
  style?: CSSProperties;
  /** Take focus on mount; `'select'` also selects the whole document. */
  autoFocus?: boolean | "select";
  /** With `autoFocus`, put the caret here instead of selecting everything. */
  cursorAt?: number;
  /** With `autoFocus`, select exactly this range — the slot that was clicked, not the whole line. */
  selectRange?: { from: number; to: number };
  /** Pin every line to this height so lines can sit on a host's own rows. */
  lineHeightPx?: number;
  align?: "left" | "right";
  /** Extra chrome rendered inside the block's frame, positioned by the host's CSS. */
  trailing?: ReactNode;
  /**
   * Enter (single-line) / Ctrl+Enter (multi) and Escape both end the
   * gesture by leaving the block (the value is never discarded — Ctrl+Z is
   * the retract). A host that owns its own editing session supplies its
   * own exits instead of the default `leave`.
   */
  onEnter?(): void;
  onEscape?(): void;
  onViewReady?(view: EditorView): void;
  /**
   * Controlled two-way toggle between the pretty RENDERED tree
   * (`grammar.lines`) and the live SOURCE document (CodeMirror) — the "code
   * block overlay" idea: rendered by default, source under the caret. Omit
   * entirely for a block that is always source (the original, and still
   * the right choice for a plain port row with nothing worth a read view).
   * The host owns the state; `CodeBlock` never flips it on its own.
   */
  mode?: "rendered" | "source";
  /** Used by the optional `CodeBlockModeToggle` sub-component; `CodeBlock` itself never calls this. */
  onModeChange?(mode: "rendered" | "source"): void;
  /**
   * A rendered row (or the blank space below the last one) was clicked.
   * Only meaningful with `mode` set. `owner` is `undefined` for a row from
   * this block's own `value` — the host typically responds by setting
   * `mode="source"` and computing `cursorAt` from `line`/`column` (see
   * `caretGeometry.ts`'s `lineStartOffset`) against `value` itself. `owner`
   * is set for a row that came from a reference's `expandLines()` (see
   * `CodeBlockReference.owner`) — `line`/`column` are into THAT source, not
   * this block's `value`, and the host must resolve `owner` to open it.
   */
  onOpenSource?(line: number, column: number, owner?: unknown): void;
  /**
   * Where the completion popup (and any other CodeMirror tooltip) is
   * parented. Takes priority over an ancestor `[data-tooltip-host]`; both
   * are host opt-ins, so the core stays free of any specific canvas
   * engine's name. A function is called once per mount. Defaults to the
   * nearest `[data-tooltip-host]` ancestor, else `document.body`.
   */
  tooltipParent?: HTMLElement | (() => HTMLElement | null);
}

/**
 * The code block: a CodeMirror document in a box — and the code FIELD, which
 * is the same box wearing `look="field"`.
 *
 * WHY one component and not `CodeField` + `CodeBlock` (Zach, 2026-09-14:
 * "refactor codefield to actually just be codeblock ... the code field is
 * basically just like a codeblock without line numbers, right? I feel it's
 * the exact same thing"): it is. Every difference between the one-line box
 * in a Port's label slot and the canvas Code block is a VALUE — a gutter on
 * or off, one line or many, 4px or 16px of padding, 11px or 16px of type —
 * never a different engine, gesture or commit rule. SystemSketch reached the
 * same conclusion from the other side (its PEP 0017 converged four
 * CodeMirror mounts onto one field); this primitive is that field with the
 * block's presentation knobs folded in as fields, so the inspector, the
 * registry and a Port all see one thing. The tempting alternative — keep a
 * thin `CodeField` wrapper "for the name" — is two names for one property
 * space, and the first refactor to touch only one of them drifts the pair.
 *
 * What the block does NOT know is any grammar — that arrives through
 * `grammar`, so a port line, a type alias and a plain label are the same
 * component with different grammars plugged in. Commit semantics are
 * `FieldGesture`'s, unchanged: a block never stops existing with an
 * uncommitted edit.
 *
 * With `mode` set, this is a thin dispatcher: `"rendered"` mounts
 * `CodeBlockRows` over `grammar.lines(value)` and CodeMirror never mounts at
 * all; `"source"` (or `mode` omitted) mounts the live document below. The
 * two never coexist — leaving rendered mode unmounts the row tree exactly
 * as `CodeBlockSourceView` unmounts when rendered mode takes over — so a
 * grammar with no `lines()` still works fine as an always-source block.
 *
 * WHY expansion state lives HERE and not inside `CodeBlockRows`: `CodeBlock`
 * itself is the one component instance that survives the `mode` toggle (only
 * its RETURNED subtree switches between the row tree and the live document);
 * `CodeBlockRows` fully unmounts every trip through Source. State that lived
 * only there reset to all-collapsed on every round trip even when nothing
 * was edited — the donor (`TypeBabbleV1.tsx`) lifts the same state for the
 * same reason, above its own UI/Source split.
 */
export interface CodeBlockHandle {
  /**
   * Move the caret to `offset` and focus the live document — the seam an
   * ALREADY-MOUNTED-in-Source block needs. `cursorAt` only places the
   * caret once, in the mount effect (`autoFocus`'s own next-frame retry);
   * a host whose owner block is already open in Source when a foreign row
   * is clicked has no prop change to hand it, since `cursorAt` changing
   * while mounted does nothing — the donor's `useSourceToggleEditor`
   * solves the identical problem with `enterSourceAt`'s "already open …
   * place the caret on the live view directly" branch. A no-op while
   * `mode === "rendered"` (no live document to place a caret in).
   */
  setCaret(offset: number): void;
  focus(): void;
}

export const CodeBlock = forwardRef<CodeBlockHandle, CodeBlockProps>(function CodeBlock(props, ref) {
  const { mode, grammar, value, onOpenSource, ariaLabel, className, testId } = props;
  const [expandedPaths, setExpandedPaths] = useState<ReadonlySet<string>>(() => new Set());
  const toggleExpanded = (path: string) =>
    setExpandedPaths((current) => {
      const next = new Set(current);
      if (next.has(path)) next.delete(path);
      else next.add(path);
      return next;
    });
  const lines = grammar?.lines?.(value) ?? [];
  // Prune expansion keys an edit has deleted outright — see
  // `pruneExpandedPaths`'s own doc for what this does and does not fix.
  useEffect(() => {
    setExpandedPaths((current) => pruneExpandedPaths(current, lines));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lines.map(rowIdentity).join(",")]);
  const sourceRef = useRef<CodeBlockHandle | null>(null);
  useImperativeHandle(ref, () => ({
    setCaret: (offset) => sourceRef.current?.setCaret(offset),
    focus: () => sourceRef.current?.focus(),
  }), []);
  if (mode === "rendered") {
    return (
      <CodeBlockRows
        lines={lines}
        resolveReference={grammar?.resolveReference}
        onOpenSource={onOpenSource}
        expandedPaths={expandedPaths}
        onToggleExpanded={toggleExpanded}
        className={className}
        testId={testId}
      />
    );
  }
  return <CodeBlockSourceView {...props} ariaLabel={ariaLabel} ref={sourceRef} />;
});

/** Two-button `[Rendered | Source]` switch — the chrome `CodeBlock`'s `mode` toggle needs, matching how it looks on the field this was extracted from. Entirely optional: a host may drive `mode` from its own UI instead. */
export function CodeBlockModeToggle({
  mode,
  onModeChange,
  labels = { rendered: "UI", source: "Source" },
}: {
  mode: "rendered" | "source";
  onModeChange(mode: "rendered" | "source"): void;
  labels?: { rendered: string; source: string };
}) {
  return (
    <div className="bbox-code-block-toggle" data-slot="code-block-mode-toggle">
      <button type="button" data-active={mode === "rendered" || undefined} onClick={() => onModeChange("rendered")}>
        {labels.rendered}
      </button>
      <button type="button" data-active={mode === "source" || undefined} onClick={() => onModeChange("source")}>
        {labels.source}
      </button>
    </div>
  );
}

/**
 * The look-resolved presentation of a CodeBlock: every governed field is its
 * explicit prop when given, else its `look`'s value. Exported so a test (and
 * a host that lays a block out before mounting it, e.g. a tldraw adapter
 * deciding `props.w`) reads the exact numbers the component paints from.
 */
export function resolveCodeBlockPresentation(props: {
  look?: CodeBlockLook;
  size?: CodeBlockSize;
  sizePx?: number;
  lineNumbers?: boolean;
  lines?: CodeBlockLines;
  overflow?: CodeBlockOverflow;
  columns?: number;
  paddingTop?: number;
  paddingBot?: number;
  paddingLeft?: number;
  paddingRight?: number;
}) {
  const look = props.look ?? "block";
  const fromLook = codeBlockLookValues(look);
  const fontPx = codeBlockFontPx(props.size ?? "md", props.sizePx ?? 16);
  const lineNumbers = props.lineNumbers ?? fromLook.lineNumbers;
  const overflow = props.overflow ?? fromLook.overflow;
  const paddingLeft = props.paddingLeft ?? fromLook.paddingLeft;
  const paddingRight = props.paddingRight ?? fromLook.paddingRight;
  return {
    look,
    fontPx,
    lineNumbers,
    lines: props.lines ?? fromLook.lines,
    overflow,
    paddingTop: props.paddingTop ?? fromLook.paddingTop,
    paddingBot: props.paddingBot ?? fromLook.paddingBot,
    paddingLeft,
    paddingRight,
    // `grow` means the TEXT decides the width, so an authored column count
    // is set aside rather than fought — the box is as wide as its longest
    // line, whatever `columns` says. `grow-truncated` grows the same way;
    // there `columns` is the fold width of the lines the caret is not on.
    width: codeBlockGrows(overflow) ? undefined : codeBlockWidthPx(props.columns ?? 0, fontPx, lineNumbers, paddingLeft, paddingRight),
  };
}

const CodeBlockSourceView = forwardRef<CodeBlockHandle, CodeBlockProps>(function CodeBlockSourceView({
  value,
  onWrite,
  beginEdit,
  onEditEnd,
  grammar,
  look = "block",
  language = "python",
  size = "md",
  sizePx = 16,
  lineNumbers,
  lines,
  overflow,
  flatten = false,
  columns = 0,
  paddingTop,
  paddingBot,
  paddingLeft,
  paddingRight,
  expandable = false,
  onExpand,
  editing = true,
  disabled = false,
  placeholder,
  ariaLabel,
  ariaDescribedBy,
  ariaInvalid,
  className,
  testId,
  style,
  autoFocus = false,
  cursorAt,
  selectRange,
  lineHeightPx,
  align = "left",
  trailing,
  onEnter,
  onEscape,
  onViewReady,
  tooltipParent,
}, ref) {
  const presentation = resolveCodeBlockPresentation({
    look,
    size,
    sizePx,
    lineNumbers,
    lines,
    overflow,
    columns,
    paddingTop,
    paddingBot,
    paddingLeft,
    paddingRight,
  });
  const multiline = presentation.lines === "multi";
  const wrap = presentation.overflow === "wrap";
  // A live document: editable AND not read-only. `editing` is the host's
  // session flag; `disabled` is the document's own read-only fact.
  const live = editing && !disabled;

  const hostRef = useRef<HTMLDivElement>(null);
  const viewRef = useRef<EditorView | null>(null);
  const grammarCompartment = useRef(new Compartment());
  const languageCompartment = useRef(new Compartment());
  const chromeCompartment = useRef(new Compartment());
  const editableCompartment = useRef(new Compartment());
  const placeholderCompartment = useRef(new Compartment());
  const metricsCompartment = useRef(new Compartment());

  const latest = useRef({
    onWrite,
    beginEdit,
    onEditEnd,
    onEnter,
    onEscape,
    value,
    live,
    multiline,
  });
  latest.current = {
    onWrite,
    beginEdit,
    onEditEnd,
    onEnter,
    onEscape,
    value,
    live,
    multiline,
  };

  const metrics = (): Extension => [
    EditorView.theme({
      ...(lineHeightPx
        ? { ".cm-line": { lineHeight: `${lineHeightPx}px`, height: `${lineHeightPx}px` } }
        : {}),
      ...(align === "right" ? { ".cm-content": { textAlign: "right" } } : {}),
    }),
    ...(wrap ? [EditorView.lineWrapping] : []),
  ];

  // The look's own chrome: the gutter (counting units under `flatten`),
  // Tab-as-indent in a document (never in a one-line box, where Tab must
  // keep walking focus), and the flatten fold itself.
  const units = grammar?.units ?? pythonUnits;
  const truncated = presentation.overflow === "grow-truncated";
  const chrome = (): Extension => [
    ...(presentation.lineNumbers ? [flatten ? flattenLineNumbers(units) : lineNumbersExtension()] : []),
    ...(multiline ? [keymap.of([indentWithTab])] : []),
    ...(flatten ? [flattenDecorations(units)] : []),
    // Every line the caret is NOT on folds after `columns` characters; the
    // caret's line shows in full and the box grows to it.
    ...(truncated ? [foldInactiveLines(columns > 0 ? Math.round(columns) : CODE_BLOCK_TRUNCATE_DEFAULT_COLUMNS)] : []),
  ];

  // The base parser: the `language` prop, unless the grammar mounts its
  // own raw `language` extension (a grammar that brings a parser owns it —
  // two parsers on one document would fight over highlighting).
  const baseLanguage = (): Extension => (grammar?.language ? [] : codeBlockLanguageExtension(language));

  const gestureRef = useRef<FieldGesture | null>(null);
  if (!gestureRef.current) {
    gestureRef.current = new FieldGesture(
      {
        write: (next) => latest.current.onWrite(next),
        begin: () => latest.current.beginEdit?.(),
        end: (next, start) => latest.current.onEditEnd?.(next, start),
      },
      "live",
    );
  }
  const gesture = gestureRef.current;

  const leave = (view: EditorView) => {
    view.contentDOM.blur();
    gesture.commit();
  };

  useImperativeHandle(ref, () => ({
    setCaret: (offset) => {
      const view = viewRef.current;
      if (!view) return;
      const anchor = Math.max(0, Math.min(offset, view.state.doc.length));
      // WHY the scrollIntoView effect, not just a selection dispatch: on a
      // multi-line lane taller than its scroll host, an owner-jump can
      // land the caret well below the visible viewport (measured: y 557
      // in a 40px-tall host) with nothing on screen to show it happened.
      view.dispatch({ selection: { anchor }, effects: EditorView.scrollIntoView(anchor) });
      view.focus();
    },
    focus: () => viewRef.current?.focus(),
  }), []);

  useLayoutEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const view = new EditorView({
      state: EditorState.create({
        doc: value,
        extensions: [
          history(),
          // Enter and Escape are the block's exits, handled on the raw event
          // so the keystroke can be STOPPED: once the block closes, the same
          // keydown would otherwise reach a host's own document listener
          // with nothing focused — a canvas host that re-enters editing on
          // Enter, or clears a selection on Escape, would immediately undo
          // the exit. A completion popup gets first refusal on a BARE
          // Enter/Escape — its own keymap (Prec.highest inside
          // `autocompletion()`) accepts or closes it. The MODIFIER form
          // (Ctrl/Cmd+Enter) is our own dedicated exit and must never fall
          // through to it: `defaultKeymap`'s Mod-Enter is `insertBlankLine`,
          // which used to run whenever a popup happened to be open, leaving
          // a newline in even a single-line box. Accept-or-close the
          // popup ourselves first, then exit.
          Prec.high(
            EditorView.domEventHandlers({
              keydown: (event, target) => {
                if (event.isComposing) return false;
                if (event.key !== "Enter" && event.key !== "Escape") return false;
                const completionActive = completionStatus(target.state) === "active";
                const modifierEnter = event.key === "Enter" && (event.ctrlKey || event.metaKey);
                if (completionActive && !modifierEnter) {
                  // A bare Enter accepts the popup, Escape closes it —
                  // CodeMirror's own completion keymap runs independently of
                  // native DOM bubbling, so returning `false` here still lets
                  // it fire. But native bubbling itself must still be cut:
                  // a host's OWN document-level keydown listener (tldraw
                  // cancels the whole editing session on Escape, with no
                  // shortcuts gate) would otherwise see the same event and
                  // react to it too, on top of the popup closing.
                  event.stopPropagation();
                  return false;
                }
                // In a document a bare Enter is a new line; only the modifier form exits.
                if (event.key === "Enter" && latest.current.multiline && !modifierEnter) {
                  return false;
                }
                if (completionActive && modifierEnter) acceptCompletion(target);
                event.preventDefault();
                event.stopPropagation();
                const exit = event.key === "Enter" ? latest.current.onEnter : latest.current.onEscape;
                if (exit) exit();
                else leave(target);
                return true;
              },
            }),
          ),
          // The transaction-level backstop for the single-line contract
          // above: whatever inserts a newline — typed/pasted text (caught
          // below by the input handler too), or a COMMAND like
          // `insertBlankLine` reached via the fallback this same keydown
          // handler used to allow — never survives in a single-line box.
          singleLineGuard(() => latest.current.multiline),
          // A document is a small IDE buffer, so the line keys people reach
          // for all work: CodeMirror's own Alt+↑/↓ and Shift+Alt+↑/↓, plus
          // the Ctrl forms for anyone whose window manager eats Alt+arrows.
          keymap.of([
            { key: "Ctrl-ArrowUp", run: moveLineUp },
            { key: "Ctrl-ArrowDown", run: moveLineDown },
            { key: "Ctrl-Shift-ArrowUp", run: copyLineUp },
            { key: "Ctrl-Shift-ArrowDown", run: copyLineDown },
            ...defaultKeymap,
            ...historyKeymap,
          ]),
          languageCompartment.current.of(baseLanguage()),
          syntaxHighlighting(classHighlighter),
          grammarCompartment.current.of(grammar ? grammarExtensions(grammar) : []),
          chromeCompartment.current.of(chrome()),
          editableCompartment.current.of(EditorView.editable.of(live)),
          placeholderCompartment.current.of(placeholder ? placeholderExtension(placeholder) : []),
          metricsCompartment.current.of(metrics()),
          // The completion popup is parented to an explicit `tooltipParent`
          // if the caller gave one, else the nearest declared tooltip host
          // (`[data-tooltip-host]` — a modal, a canvas layer, anything that
          // must keep the popup inside its own stacking context), else the
          // document body. WHY the ancestor lookup exists at all, beside the
          // prop: a host mounting many blocks (every row of a canvas) can
          // opt every one of them in at once by tagging a single container,
          // rather than threading `tooltipParent` through each — the block
          // stays host-agnostic either way, since neither path names a
          // specific canvas engine.
          tooltips({
            position: "absolute",
            parent:
              (typeof tooltipParent === "function" ? tooltipParent() : tooltipParent) ??
              host.closest<HTMLElement>("[data-tooltip-host]") ??
              document.body,
          }),
          // One line: a typed or pasted newline is dropped rather than
          // growing the box. A document keeps its newlines — they are its rows.
          EditorView.inputHandler.of((target, from, to, insertedText) => {
            if (latest.current.multiline || !/[\r\n]/.test(insertedText)) return false;
            const cleaned = insertedText.replace(/[\r\n]+/g, "");
            target.dispatch({
              changes: { from, to, insert: cleaned },
              selection: { anchor: from + cleaned.length },
            });
            return true;
          }),
          EditorView.updateListener.of((update) => {
            if (!update.docChanged) return;
            if (update.transactions.every((tr) => tr.annotation(externalSync))) return;
            const text = update.state.doc.toString();
            gesture.focus(latest.current.value);
            gesture.change(text);
          }),
          EditorView.domEventHandlers({
            focus: () => {
              if (!latest.current.live) return;
              gesture.focus(latest.current.value);
            },
            // A CodeMirror `contentDOM` can flicker focus during its own
            // mount work; a synchronous commit on the first flicker would
            // end the gesture the instant it began. Believed only once it
            // survives a macrotask.
            blur: () => {
              globalThis.setTimeout(() => {
                const current = viewRef.current;
                if (current && !current.hasFocus) gesture.commit();
              }, 0);
            },
          }),
        ],
      }),
      parent: host,
    });
    viewRef.current = view;
    onViewReady?.(view);
    // Focus now and again on the next frame: a host that is mid-transition
    // (a canvas entering its own editing state) can take focus back after
    // the first attempt, and a block that opened without focus is a dead
    // block.
    let frame = 0;
    if (autoFocus) {
      const take = () => {
        if (view.hasFocus || !viewRef.current) return;
        view.focus();
        const length = view.state.doc.length;
        if (selectRange) {
          const anchor = Math.max(0, Math.min(selectRange.from, length));
          const head = Math.max(anchor, Math.min(selectRange.to, length));
          view.dispatch({ selection: { anchor, head } });
        } else if (cursorAt !== undefined) {
          const anchor = Math.max(0, Math.min(cursorAt, length));
          view.dispatch({ selection: { anchor } });
        } else if (autoFocus === "select") {
          view.dispatch({ selection: { anchor: 0, head: view.state.doc.length } });
        }
      };
      take();
      frame = requestAnimationFrame(take);
    }
    return () => {
      cancelAnimationFrame(frame);
      viewRef.current = null;
      view.destroy();
    };
    // One mount for the block's lifetime; content, grammar and editability
    // flow through compartments and dispatches so a re-render never tears
    // the document down mid-gesture.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // The document follows the store whenever nobody is typing in it. Every
  // keystroke round-trips back through `value` (the block's one write
  // policy is `live`), so the equality guard is what keeps this from
  // re-fighting the caret.
  useEffect(() => {
    const view = viewRef.current;
    if (!view || view.state.doc.toString() === value) return;
    if (gesture.isEditing && view.hasFocus) return;
    view.dispatch({
      changes: { from: 0, to: view.state.doc.length, insert: value },
      annotations: externalSync.of(true),
    });
  }, [value, gesture]);

  useEffect(() => {
    viewRef.current?.dispatch({
      effects: grammarCompartment.current.reconfigure(grammar ? grammarExtensions(grammar) : []),
    });
  }, [grammar]);

  useEffect(() => {
    viewRef.current?.dispatch({ effects: languageCompartment.current.reconfigure(baseLanguage()) });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [language, grammar?.language]);

  useEffect(() => {
    viewRef.current?.dispatch({ effects: chromeCompartment.current.reconfigure(chrome()) });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [presentation.lineNumbers, multiline, flatten, units, truncated, columns]);

  useEffect(() => {
    viewRef.current?.dispatch({
      effects: editableCompartment.current.reconfigure(EditorView.editable.of(live)),
    });
  }, [live]);

  // Entering an editing session takes focus; leaving one gives it back.
  // WHY a transition effect and not `autoFocus`: the block mounts ONCE for
  // a host session's whole lifetime and toggles `editing` (the canvas Code
  // block's shape stays mounted across select → edit → deselect), so "just
  // entered" is a prop CHANGE, which `autoFocus` — a mount-time fact — can
  // never see. Skipped on mount so a page full of `editing` (default true)
  // Port labels doesn't fight over focus on load.
  //
  // WHY leaving ABANDONS the gesture rather than committing it: the host
  // that flipped `editing` off already knows the final value — it received
  // every keystroke through `onWrite`, and it decided the exit (Enter →
  // its own commit; Escape → its own restore). A commit here would fire
  // `onEditEnd` with the document's last typed text, which after an Escape
  // is exactly the text the host just threw away (`FieldGesture.abandon`'s
  // own WHY). The document is then resynced to `value` by hand, because the
  // ordinary resync effect skips a focused, mid-gesture document on purpose.
  const previousLive = useRef(live);
  useEffect(() => {
    const was = previousLive.current;
    previousLive.current = live;
    if (was === live) return;
    const view = viewRef.current;
    if (!view) return;
    if (live) {
      const frame = requestAnimationFrame(() => {
        if (!viewRef.current || viewRef.current.hasFocus) return;
        viewRef.current.focus();
        const end = viewRef.current.state.doc.length;
        viewRef.current.dispatch({ selection: { anchor: end } });
      });
      return () => cancelAnimationFrame(frame);
    }
    gesture.abandon();
    if (view.hasFocus) view.contentDOM.blur();
    const stored = latest.current.value;
    if (view.state.doc.toString() !== stored) {
      view.dispatch({
        changes: { from: 0, to: view.state.doc.length, insert: stored },
        annotations: externalSync.of(true),
      });
    }
    return undefined;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [live]);

  useEffect(() => {
    viewRef.current?.dispatch({ effects: metricsCompartment.current.reconfigure(metrics()) });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lineHeightPx, align, wrap]);

  useEffect(() => {
    viewRef.current?.dispatch({
      effects: placeholderCompartment.current.reconfigure(
        placeholder ? placeholderExtension(placeholder) : [],
      ),
    });
  }, [placeholder]);

  // A canvas host typically calls `preventDefault()` on its own pointerdown,
  // so clicking the canvas never fires this block's native blur. A
  // capture-phase listener on `document` is the one place "clicked outside
  // the block" is observable regardless of what swallowed the native event.
  useEffect(() => {
    const handlePointerDown = (event: PointerEvent) => {
      const host = hostRef.current;
      const view = viewRef.current;
      if (!host || !view || !view.hasFocus) return;
      if (event.target instanceof Node && host.contains(event.target)) return;
      const element =
        event.target instanceof Element ? event.target : (event.target as Node | null)?.parentElement;
      if (element?.closest(".cm-tooltip")) return;
      leave(view);
    };
    document.addEventListener("pointerdown", handlePointerDown, true);
    return () => document.removeEventListener("pointerdown", handlePointerDown, true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // A canvas host typically wires wheel on an ancestor for its own pan/zoom
  // (tldraw on its container, React Flow on its pane), which fires from a
  // wheel over ANY of its children including this one — scrolling inside a
  // focused block would otherwise zoom or pan the whole canvas underneath
  // it. `{ passive: false }` + a real listener (not React's synthetic wheel,
  // which React attaches passively by default and cannot stop natively)
  // is what actually keeps the native event from bubbling past us.
  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const handleWheel = (event: WheelEvent) => {
      if (viewRef.current?.hasFocus) event.stopPropagation();
    };
    host.addEventListener("wheel", handleWheel, { passive: false });
    return () => host.removeEventListener("wheel", handleWheel);
  }, []);

  // Unmount is an end boundary like any other — the one the browser refuses
  // to report, since no blur fires for a focused element removed from the DOM.
  useEffect(() => () => gesture.commit(), [gesture]);

  // WHY pointer events are only stopped while `live`: a block at rest inside
  // a canvas shape must let the host's own drag/select gesture through
  // (SystemSketch's Code block needed exactly this `stopPropagation ===
  // isEditing` seam, PEP 0017); a block being edited must own its pointer so
  // a caret click never re-runs the host's selection. The `bbox-interactive`
  // marker (class AND attribute — TextBox's own host-neutral pair) rides the
  // same flag, so React Flow's `noDragClassName` and tldraw's attribute
  // gate see "editing" and "at rest" as different things.
  const stop = live ? (event: { stopPropagation: () => void }) => event.stopPropagation() : undefined;

  const boxStyle: CSSProperties = {
    fontSize: presentation.fontPx,
    paddingTop: presentation.paddingTop,
    paddingBottom: presentation.paddingBot,
    paddingLeft: presentation.paddingLeft,
    paddingRight: presentation.paddingRight,
    // `grow`: the box is exactly as wide as its content (the stylesheet's
    // own `width: 100%` would otherwise pin it to the host). WHY `flex:
    // none` and `minWidth` ride along: inside a flex host (a Block slot's
    // Flex on /create) a `width: max-content` item still SHRINKS — flex
    // items default to `flex-shrink: 1` down to their min-content width,
    // and a scrolling CodeMirror's min-content is nearly zero, so the box
    // measured exactly the slot's width and never grew. Refusing to shrink
    // is what "resize the width to match the text" means; overflowing the
    // slot is then the host's to allow or clip.
    ...(codeBlockGrows(presentation.overflow) ? { width: "max-content", minWidth: "max-content", flex: "none" } : {}),
    ...(presentation.width !== undefined ? { width: presentation.width } : {}),
  };

  return (
    <div
      data-slot="code-block"
      data-look={presentation.look}
      data-language={language}
      data-size={size}
      data-lines={presentation.lines}
      data-line-numbers={presentation.lineNumbers}
      data-overflow={presentation.overflow}
      data-flatten={flatten}
      data-editing={editing}
      {...(live ? { "data-bbox-interactive": "" } : {})}
      className={`bbox-code-block bbox-code-tokens${live ? " bbox-interactive" : ""}${className ? ` ${className}` : ""}`}
      ref={hostRef}
      role="textbox"
      aria-label={ariaLabel}
      aria-describedby={ariaDescribedBy}
      aria-invalid={ariaInvalid ? true : undefined}
      aria-disabled={disabled ? true : undefined}
      aria-readonly={!editing && !disabled ? true : undefined}
      aria-multiline={multiline ? true : undefined}
      data-testid={testId}
      style={{ ...boxStyle, ...style }}
      onPointerDown={stop}
      onClick={stop}
      onDoubleClick={stop}
    >
      {trailing}
      {expandable ? (
        // WHY the button stops its own pointerdown regardless of `editing`:
        // it is the one thing on a resting block that must NOT start the
        // host's drag — a press on it means "open the larger view", never
        // "move the shape" — while the rest of the resting box still lets
        // the host's gesture through (the `stop` seam above).
        <button
          type="button"
          data-slot="code-block-expand"
          className="bbox-code-block-expand"
          aria-label="Expand to a larger view"
          title="Expand"
          onPointerDown={(event) => event.stopPropagation()}
          onClick={(event) => {
            event.stopPropagation();
            onExpand?.();
          }}
        >
          ⤢
        </button>
      ) : null}
    </div>
  );
});

/*
 * The code block — and the code FIELD, which is the same box wearing
 * `data-look="field"` (see codeBlock.tsx's own WHY). Colours are bbox-ui's
 * own tokens (see theme.css), so the box follows whatever theme the
 * surrounding kit is painted with.
 *
 * Size, padding and width are NOT set here: the component writes them
 * inline from its resolved presentation (`resolveCodeBlockPresentation`),
 * so the stylesheet never has an opinion the inspector has to fight. What
 * lives here is chrome only — border, radius, the gutter, the caret, the
 * selection, the popup — keyed by look where the two looks differ.
 */

.bbox-code-block {
  position: relative;
  display: block;
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  border: 1px solid var(--color-border);
  background: var(--color-card);
  color: var(--color-foreground);
  cursor: text;
  overflow: hidden;
}

/* The field look sits where an <input> sat; the block look is a surface
   (SystemSketch's Code block: 10px radius). */
.bbox-code-block[data-look="field"] {
  border-radius: 6px;
}

.bbox-code-block[data-look="block"] {
  border-radius: 10px;
}

.bbox-code-block[aria-disabled="true"] {
  opacity: 0.6;
  cursor: default;
}

/* At rest inside a host's editing session (`editing={false}`, NOT
   disabled) the block is its normal, fully legible read view, not a
   dimmed control — and the pointer is the host's (drag, select). */
.bbox-code-block[data-editing="false"] {
  cursor: default;
}

.bbox-code-block:focus-within,
.bbox-code-block[data-editing="true"]:focus-within {
  border-color: var(--color-primary);
}

/*
 * CodeMirror parents its tooltips (the completion popup) onto whatever
 * `tooltipParent`/`[data-tooltip-host]` names — document.body by default,
 * NOT a descendant of `.bbox-code-block`, so this deliberately is not a
 * `.bbox-code-block .cm-tooltip` descendant selector (it would never
 * match). A host mounting the block inside its own stacked canvas content
 * (a tldraw `HTMLContainer` shape, a React Flow node) can paint a LATER
 * shape or node on top of an EARLIER one at any DOM depth; this is the
 * floor that beats it regardless of what the host's own shapes use — the
 * donor's own value, max signed 32-bit, "it needs to go to maximum z
 * level" (Zach's call, ported).
 *
 * WHY `.cm-tooltip.bbox-code-completion` + `!important`, not a bare
 * `.cm-tooltip` rule: CodeMirror's own base theme injects a same-stylesheet
 * rule shaped like `.ͼ1 .cm-tooltip { z-index: 500 }` — two class selectors,
 * specificity (0,2,0). A bare `.cm-tooltip` is (0,1,0) and loses outright,
 * source order never even gets consulted. `.bbox-code-completion` is a class
 * `codeGrammar.ts` adds to EVERY completion popup via `autocompletion`'s
 * `tooltipClass`, so pairing it with `.cm-tooltip` reaches the same (0,2,0)
 * specificity as CodeMirror's own rule — a tie this stylesheet's load order
 * is not guaranteed to win — so `!important` is what actually decides it.
 * A consumer with other unrelated CodeMirror instances on the page should
 * scope this rule tighter after install.
 */
.cm-tooltip.bbox-code-completion {
  z-index: 2147483647 !important;
}

.bbox-code-block .cm-editor {
  outline: none;
  background: transparent;
  height: auto;
}

.bbox-code-block .cm-scroller {
  font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  /* Inherits from `.bbox-code-block`'s inline font-size (the resolved
     `size`/`sizePx`) rather than hardcoding its own — the only way a
     per-instance size can reach CodeMirror's own internal DOM. */
  font-size: inherit;
  line-height: 1.4;
}

/* A block reads at a document's leading. */
.bbox-code-block[data-look="block"] .cm-scroller {
  line-height: 1.45;
}

/* `overflow` (codeBlock.layout.ts): what a line wider than the box does.
   clip — an input: cut at the edge, no bar. scroll — a bar (CodeMirror's
   own scroller). wrap — `lineWrapping` folds the line (the `.cm-lineWrapping`
   rule below). grow — the box itself is `max-content` wide (inline style),
   so nothing is ever wider than it and the scroller can stay visible. */
.bbox-code-block[data-overflow="clip"] .cm-scroller {
  overflow: hidden;
}

.bbox-code-block[data-overflow="scroll"] .cm-scroller,
.bbox-code-block[data-overflow="wrap"] .cm-scroller {
  overflow: auto;
}

.bbox-code-block[data-overflow="grow"] .cm-scroller,
.bbox-code-block[data-overflow="grow-truncated"] .cm-scroller {
  overflow: visible;
}

/* The ⤢ corner button (`expandable`): quiet until hovered, and it never
   takes room from the text — it floats over the top-right padding. */
.bbox-code-block-expand {
  position: absolute;
  top: 4px;
  right: 4px;
  z-index: 1;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 4px;
  background: transparent;
  color: var(--color-muted-foreground);
  font: inherit;
  font-size: 13px;
  line-height: 18px;
  text-align: center;
  cursor: pointer;
  opacity: 0.55;
}

.bbox-code-block-expand:hover,
.bbox-code-block-expand:focus-visible {
  opacity: 1;
  border-color: var(--color-border);
  background: var(--color-muted);
  color: var(--color-foreground);
  outline: none;
}

.bbox-code-block .cm-content {
  padding: 0;
  caret-color: var(--color-primary);
  white-space: nowrap;
}

/* WHY this rule exists at all: CodeMirror's `lineWrapping` sets
   `white-space: pre-wrap` through its own `.ͼ1 .cm-lineWrapping` rule —
   specificity (0,2,0), the SAME as the `nowrap` above, so which wins would
   otherwise depend on stylesheet order. Three classes settles it. */
.bbox-code-block .cm-content.cm-lineWrapping {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.bbox-code-block .cm-line {
  padding: 0;
}

/* The line-number gutter (`lineNumbers`): SystemSketch's own quiet gutter —
   no fill, a hairline on its right, numbers in the faint ink, room for
   three digits before the content's own padding starts. */
.bbox-code-block .cm-gutters {
  background: transparent;
  color: var(--color-muted-foreground);
  border-right: 1px solid var(--color-border);
  min-width: 36px;
  justify-content: flex-end;
  margin-right: 12px;
}

.bbox-code-block .cm-lineNumbers .cm-gutterElement {
  padding: 0 8px 0 6px;
}

.bbox-code-block .cm-focused .cm-activeLine,
.bbox-code-block .cm-focused .cm-activeLineGutter {
  background: color-mix(in srgb, var(--color-primary) 7%, transparent);
}

.bbox-code-block .cm-placeholder {
  color: var(--color-muted-foreground);
  font-style: normal;
}

.bbox-code-block .cm-selectionBackground,
.bbox-code-block .cm-focused .cm-selectionBackground,
.bbox-code-block ::selection {
  background: color-mix(in srgb, var(--color-primary) 30%, transparent);
}

.bbox-code-block .cm-cursor {
  border-left-color: var(--color-primary);
}

/*
 * The syntax palette. `classHighlighter` (@lezer/highlight) emits stable
 * `tok-*` classes with NO colour of its own; this is the one place they get
 * one, so every CodeBlock — a Port label, the canvas block, an inspector
 * row — reads as one family (SystemSketch's `pythonTokens.css`, ported).
 * Painted off the kit's own tokens (`--bbox-accent` etc., theme.css), so it
 * follows light/dark with the rest of the kit; each has a literal fallback
 * for a host that never loaded theme.css.
 *
 * WHY every selector carries BOTH root classes (0,3,0): CodeMirror's own
 * fallback highlight style, when a host happens to mount it, paints tokens
 * through generated `.ͼN .ͼM` rules at (0,2,0) — a bare
 * `.bbox-code-tokens .tok-keyword` would tie on specificity and lose or win
 * by stylesheet order. Three classes settles it in this sheet's favour.
 */
.bbox-code-block.bbox-code-tokens .tok-keyword,
.bbox-code-block.bbox-code-tokens .tok-operatorKeyword,
.bbox-code-block.bbox-code-tokens .tok-controlKeyword,
.bbox-code-block.bbox-code-tokens .tok-definitionKeyword,
.bbox-code-block.bbox-code-tokens .tok-moduleKeyword {
  color: color-mix(in srgb, var(--bbox-accent, #4f6ee5) 78%, var(--color-foreground));
  font-weight: 600;
}

.bbox-code-block.bbox-code-tokens .tok-string,
.bbox-code-block.bbox-code-tokens .tok-docString,
.bbox-code-block.bbox-code-tokens .tok-character,
.bbox-code-block.bbox-code-tokens .tok-attributeValue {
  color: color-mix(in srgb, var(--bbox-success, #2f9e5a) 62%, var(--color-foreground));
}

.bbox-code-block.bbox-code-tokens .tok-number,
.bbox-code-block.bbox-code-tokens .tok-integer,
.bbox-code-block.bbox-code-tokens .tok-float,
.bbox-code-block.bbox-code-tokens .tok-bool,
.bbox-code-block.bbox-code-tokens .tok-atom,
.bbox-code-block.bbox-code-tokens .tok-null,
.bbox-code-block.bbox-code-tokens .tok-unit {
  color: color-mix(in srgb, var(--bbox-warning, #c98a1b) 58%, var(--color-foreground));
}

.bbox-code-block.bbox-code-tokens .tok-comment,
.bbox-code-block.bbox-code-tokens .tok-lineComment,
.bbox-code-block.bbox-code-tokens .tok-blockComment,
.bbox-code-block.bbox-code-tokens .tok-meta {
  color: var(--color-muted-foreground);
  font-style: italic;
}

.bbox-code-block.bbox-code-tokens .tok-typeName,
.bbox-code-block.bbox-code-tokens .tok-className,
.bbox-code-block.bbox-code-tokens .tok-namespace {
  color: color-mix(in srgb, var(--bbox-accent, #4f6ee5) 55%, var(--color-foreground));
}

/* A bare name is the one token a board full of references most needs to
   read as "this points at something" — the accent at full strength, the
   single most saturated colour in the palette. */
.bbox-code-block.bbox-code-tokens .tok-variableName,
.bbox-code-block.bbox-code-tokens .tok-variableName2,
.bbox-code-block.bbox-code-tokens .tok-definition,
.bbox-code-block.bbox-code-tokens .tok-self {
  color: var(--bbox-accent, #4f6ee5);
}

.bbox-code-block.bbox-code-tokens .tok-propertyName,
.bbox-code-block.bbox-code-tokens .tok-attributeName,
.bbox-code-block.bbox-code-tokens .tok-labelName {
  color: color-mix(in srgb, var(--bbox-danger, #c94b3f) 42%, var(--color-foreground));
}

.bbox-code-block.bbox-code-tokens .tok-function,
.bbox-code-block.bbox-code-tokens .tok-macroName {
  color: var(--color-foreground);
  font-weight: 600;
}

.bbox-code-block.bbox-code-tokens .tok-operator,
.bbox-code-block.bbox-code-tokens .tok-punctuation,
.bbox-code-block.bbox-code-tokens .tok-separator,
.bbox-code-block.bbox-code-tokens .tok-bracket {
  color: var(--color-muted-foreground);
}

.bbox-code-block.bbox-code-tokens .tok-invalid {
  color: var(--bbox-danger, #c94b3f);
}

/* `flatten` (codeBlockFlatten.ts): the newline INSIDE a unit, shown rather
   than hidden — the glyph a return key prints, quiet, and never selectable
   as text (it is not text; the newline it stands for is). */
.bbox-code-block .bbox-code-block-newline {
  display: inline-block;
  margin: 0 3px;
  color: var(--color-muted-foreground);
  opacity: 0.75;
  font-size: 0.85em;
  line-height: 1;
  user-select: none;
  cursor: text;
}

/* Folded lane lines (`grammar.foldInactiveLinesAfter`): a quiet ellipsis,
   not a button — clicking it just moves the caret onto that line, which
   unfolds it. */
.bbox-code-block .bbox-code-block-ellipsis {
  color: var(--color-muted-foreground);
  cursor: text;
}

/* The wrapper a grammar-aware host puts around the block to carry its own
   diagnostics: a passive warning glyph and an accessible help line. Not
   part of CodeBlock itself — see the `signature` grammar's field wrapper
   for the pattern — but styled from the same sheet so the two ship together. */
.bbox-code-block-frame {
  position: relative;
  display: block;
  min-width: 0;
}

.bbox-code-block-frame[data-error="true"] .bbox-code-block {
  border-color: color-mix(in srgb, var(--bbox-danger) 60%, var(--color-border));
}

.bbox-code-block-frame__warning {
  position: absolute;
  top: 50%;
  right: 6px;
  transform: translateY(-50%);
  color: var(--bbox-warning);
  font-size: 11px;
  line-height: 1;
  pointer-events: none;
}

.bbox-code-block-frame__help {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* The `signature` grammar's three roles: the name carries the ink, the type
 * is an accent-tinted hint, the default is a muted value, and the two
 * glyphs between them are quieter than any of the three. These win over the
 * generic syntax token colours on purpose — a free-text name of three words
 * must not light up as three variable references. */
.bbox-code-block .bbox-sig-name,
.bbox-code-block .bbox-sig-name.tok-variableName {
  color: var(--color-foreground);
  font-weight: 600;
}

.bbox-code-block .bbox-sig-type,
.bbox-code-block .bbox-sig-type.tok-variableName {
  color: color-mix(in srgb, var(--color-primary) 55%, var(--color-foreground));
  font-weight: 400;
}

.bbox-code-block .bbox-sig-punct {
  color: var(--color-muted-foreground);
}

.bbox-code-block .bbox-sig-default {
  color: var(--color-foreground);
}

/*
 * RENDERED mode (`CodeBlock`'s `mode="rendered"`, `CodeBlockRows`): the same
 * three roles as source mode's marks, painted as React children instead of
 * CodeMirror decorations. `.bbox-code-seg--*` mirrors `.bbox-sig-*` above —
 * a grammar that reuses the `signature` role names gets one palette for
 * both modes for free.
 */
.bbox-code-block-rows {
  font-family: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  font-size: 11px;
  line-height: 1.6;
  color: var(--color-foreground);
  cursor: text;
}

.bbox-code-block-row {
  display: flex;
  flex-direction: column;
}

.bbox-code-block-row-content {
  display: flex;
  align-items: baseline;
  white-space: pre;
}

.bbox-code-block-chevron {
  display: inline-flex;
  width: 12px;
  flex-shrink: 0;
  color: var(--color-muted-foreground);
  font-size: 9px;
  cursor: default;
}

.bbox-code-block-chevron[role="button"] {
  cursor: pointer;
}

.bbox-code-block-preview {
  margin-left: 12px;
  padding-left: 8px;
  border-left: 1px solid var(--color-border);
}

.bbox-code-seg--name {
  color: var(--color-foreground);
  font-weight: 600;
}

.bbox-code-seg--type {
  color: color-mix(in srgb, var(--color-primary) 55%, var(--color-foreground));
}

.bbox-code-seg--default {
  color: var(--color-foreground);
}

.bbox-code-seg--punct {
  color: var(--color-muted-foreground);
}

/* A reference segment: underlined and clickable only once it resolves —
 * `resolveReference` returning `null` (an unknown name) leaves it looking
 * like ordinary accent text, matching source mode's plain `tok-variableName`
 * treatment for the same case. */
.bbox-code-ref[role="button"] {
  text-decoration: underline;
  text-underline-offset: 2px;
  cursor: pointer;
}

.bbox-code-ref--unknown {
  color: var(--bbox-danger);
}

/* `CodeBlockModeToggle` — a small [Rendered | Source] switch. */
.bbox-code-block-toggle {
  display: inline-flex;
  border: 1px solid var(--color-border);
  border-radius: 6px;
  overflow: hidden;
}

.bbox-code-block-toggle button {
  padding: 2px 8px;
  border: none;
  background: transparent;
  color: var(--color-muted-foreground);
  font-size: 11px;
  cursor: pointer;
}

.bbox-code-block-toggle button[data-active] {
  background: var(--color-muted);
  color: var(--color-foreground);
}

/* The completion tooltip's kind pill (`CodeBlockGrammar.completionBadge`). */
.bbox-code-completion-pill {
  margin-left: 6px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--color-muted);
  color: var(--color-muted-foreground);
  font-size: 10px;
  line-height: 1.6;
}

/**
 * bbox-ui CodeBlock layout — the portable geometry of the code leaf.
 *
 * CodeBlock's own size ladder, deliberately NOT `TextBox`'s (18/24/36/44 —
 * board display text) and NOT `layout.ts`'s frozen `TEXT_SIZES`: code is
 * read at editor sizes, so the rungs are SystemSketch's own Code block
 * ladder (12/16/20/24, `codeModel.ts`'s `CODE_FONT_SIZES`; Medium = 16px was
 * fixed by the V5 babble direction as the reference specimen's default).
 * React-free, engine-free, same discipline as `layout.ts`.
 */

/** CodeBlock's own ladder. Values match SystemSketch's Code block. */
export const CODE_BLOCK_SIZES = { sm: 12, md: 16, lg: 20, xl: 24 } as const;
// WHY `CodeBlockSize` widens by union rather than the table growing a fifth
// rung: "custom" has no single px value — it is the ESCAPE from the named
// ladder into `sizePx` (Port's label passes its own 11px this way), exactly
// TextBox's shape (`textBox.layout.ts`).
export type CodeBlockSize = keyof typeof CODE_BLOCK_SIZES | "custom";

/** The font-size in px for a `size`/`sizePx` pair — the one function that
 * knows "custom" escapes the named ladder. */
export function codeBlockFontPx(size: CodeBlockSize, sizePx: number): number {
  return size === "custom" ? sizePx : CODE_BLOCK_SIZES[size];
}

/**
 * The two looks one CodeBlock can wear — Zach, 2026-09-14: "the code field
 * is basically just like a codeblock without line numbers ... I feel it's
 * the exact same thing." It is. A `look` is a PRESET (`codeBlock.presets.ts`)
 * over the same fields, never a second component: `block` is the canvas
 * Code block (gutter, many lines, a surface's padding); `field` is the
 * compact one-line box that sits in a Port's label slot or an inspector row.
 */
export const CODE_BLOCK_LOOKS = ["block", "field"] as const;
export type CodeBlockLook = (typeof CODE_BLOCK_LOOKS)[number];
export const CODE_BLOCK_LOOK_LABELS: Record<CodeBlockLook, string> = {
  block: "Block",
  field: "Field",
};

/** One line (a typed or pasted newline is dropped) or a real document. */
export const CODE_BLOCK_LINES = ["single", "multi"] as const;
export type CodeBlockLines = (typeof CODE_BLOCK_LINES)[number];

/**
 * What a line that is wider than the box does — Zach, 2026-09-15: "if text
 * wrapping then it goes onto a new line; if not then you get the scroll
 * bar; if overflow, then it should resize the width to match the text."
 * Plus `clip`, the input-like behaviour a Port label already had (cut at
 * the edge, no bar, no growth), which stays the field look's default.
 * Governed by `look` (`codeBlock.presets.ts`), overridable per instance.
 */
export const CODE_BLOCK_OVERFLOWS = ["clip", "wrap", "scroll", "grow", "grow-truncated"] as const;
export type CodeBlockOverflow = (typeof CODE_BLOCK_OVERFLOWS)[number];
export const CODE_BLOCK_OVERFLOW_LABELS: Record<CodeBlockOverflow, string> = {
  clip: "Clip",
  wrap: "Wrap",
  scroll: "Scroll",
  grow: "Grow",
  // Zach, 2026-09-15: "when you have selected an active line you show the
  // full line, but when you don't have it selected you truncate it at the
  // character width and do … — truthfully display a full line, but only
  // when the cursor is on that line, otherwise more compactly." The box
  // grows like `grow`; every line the caret is NOT on folds after
  // `columns` characters (SystemSketch's expression field, ported).
  "grow-truncated": "Grow truncated",
};

/** The fold width `grow-truncated` uses when `columns` is 0 (fill). */
export const CODE_BLOCK_TRUNCATE_DEFAULT_COLUMNS = 40;

/** Both grow modes size the box to the text; only one of them folds. */
export function codeBlockGrows(overflow: CodeBlockOverflow): boolean {
  return overflow === "grow" || overflow === "grow-truncated";
}

/**
 * The languages the `language` menu offers. Same nine as SystemSketch's
 * Code block (`CODE_LANGUAGES`); `codeBlockLanguages.ts` maps each to its
 * CodeMirror package. The labels are a total Record (not a bare array) so
 * adding a tenth here is a compile error until it has a label AND a parser.
 */
export const CODE_BLOCK_LANGUAGES = [
  "plaintext",
  "python",
  "javascript",
  "typescript",
  "json",
  "html",
  "css",
  "sql",
  "markdown",
] as const;
export type CodeBlockLanguage = (typeof CODE_BLOCK_LANGUAGES)[number];
export const CODE_BLOCK_LANGUAGE_LABELS: Record<CodeBlockLanguage, string> = {
  plaintext: "Plain text",
  python: "Python",
  javascript: "JavaScript",
  typescript: "TypeScript",
  json: "JSON",
  html: "HTML",
  css: "CSS",
  sql: "SQL",
  markdown: "Markdown",
};

/** The line-number gutter's reserved width, and the mono-cell approximation
 * (glyph advance ≈ 0.61 × font-size for the ui-monospace stack) — both
 * SystemSketch's own measured constants (`CODE_GUTTER_WIDTH`,
 * `codeCharacterPixels`). */
export const CODE_BLOCK_GUTTER_PX = 36;
export const CODE_BLOCK_CHAR_RATIO = 0.61;

/** Width in px of one character cell at `fontPx`. */
export function codeBlockCharPx(fontPx: number): number {
  return Math.max(1, fontPx * CODE_BLOCK_CHAR_RATIO);
}

/**
 * The box width a CodeBlock takes to show `columns` characters — padding,
 * plus the gutter when line numbers are on, plus the cells. `columns` is
 * the AUTHORED fact ("40 ch" in the toolbar readout); pixels derive from
 * it, never the other way round. Returns `undefined` for `columns <= 0`,
 * the "fill whatever the host gives me" default.
 */
export function codeBlockWidthPx(
  columns: number,
  fontPx: number,
  lineNumbers: boolean,
  paddingLeft: number,
  paddingRight: number,
): number | undefined {
  if (!Number.isFinite(columns) || columns <= 0) return undefined;
  return Math.round(
    paddingLeft + paddingRight + (lineNumbers ? CODE_BLOCK_GUTTER_PX : 0) + Math.round(columns) * codeBlockCharPx(fontPx),
  );
}

/**
 * packages/bbox-ui/src/codeBlock.presets.ts
 *
 * `CODE_BLOCK_PRESETS` — one per `CodeBlockLook`, selected by `look`, each
 * governing the SAME six presentation fields. This is the whole answer to
 * "is a code field just a code block without line numbers?" (Zach,
 * 2026-09-14): yes — `field` and `block` are two value sets over one
 * component, the P2 "views are presets" pattern Block already uses for
 * Simple/Port/Expanded (`block.presets.ts`). An explicit prop (`lineNumbers`
 * on a `look="field"`) still wins over its look, exactly as an override
 * beats a preset everywhere else in the cascade (`@bbox-ui/schema`'s
 * `resolveField`).
 */
import {
  CODE_BLOCK_LOOK_LABELS,
  CODE_BLOCK_LOOKS,
  type CodeBlockLines,
  type CodeBlockLook,
  type CodeBlockOverflow,
} from "./codeBlock.layout";

/**
 * Structurally `@bbox-ui/schema`'s `PresetSpec`, restated here WITHOUT the
 * import. WHY: this file ships in the `code-block` registry item (shadcn
 * copies source verbatim, root CLAUDE.md), and a consumer's checkout has no
 * `@bbox-ui/schema` to resolve — even a type-only import fails their
 * typecheck. The panel still takes `CODE_BLOCK_PRESETS` as `PresetSpec[]`
 * unchanged, because the shapes are identical; `codeBlock.fields.test.ts`
 * runs the schema's own `assertDisjointPresets` over it to prove that.
 */
export interface CodeBlockPreset {
  id: string;
  label: string;
  selector: string;
  governs: string[];
  values: Record<string, string | number | boolean>;
}

export const CODE_BLOCK_LOOK_GOVERNS = [
  "lineNumbers",
  "lines",
  "overflow",
  "paddingTop",
  "paddingBot",
  "paddingLeft",
  "paddingRight",
] as const;

export interface CodeBlockLookValues {
  lineNumbers: boolean;
  lines: CodeBlockLines;
  overflow: CodeBlockOverflow;
  paddingTop: number;
  paddingBot: number;
  paddingLeft: number;
  paddingRight: number;
}

// WHY a total Record keyed by `CodeBlockLook`: a third look added to the
// vocabulary without values here is a compile error, not a preset built
// with `values: undefined` that throws the first time the panel reads it
// (pill.presets.ts learned this the hard way).
const LOOK_VALUES: Record<CodeBlockLook, CodeBlockLookValues> = {
  // The canvas Code block: SystemSketch's `code-block.css` pads the
  // scroller 10px top/bottom and the content 16px left/right.
  // A code editor scrolls a long line rather than folding it (the source
  // stays truthful to its own columns).
  block: { lineNumbers: true, lines: "multi", overflow: "scroll", paddingTop: 10, paddingBot: 10, paddingLeft: 16, paddingRight: 16 },
  // The one-line box "sized to sit where a plain <input> sat" — the old
  // `.bbox-code-field`'s own 4px 6px, and an input's clip at the edge.
  field: { lineNumbers: false, lines: "single", overflow: "clip", paddingTop: 4, paddingBot: 4, paddingLeft: 6, paddingRight: 6 },
};

export const CODE_BLOCK_PRESETS: CodeBlockPreset[] = CODE_BLOCK_LOOKS.map((look) => ({
  id: look,
  label: CODE_BLOCK_LOOK_LABELS[look],
  selector: "look",
  governs: [...CODE_BLOCK_LOOK_GOVERNS],
  values: { ...LOOK_VALUES[look] },
}));

/** The values a look carries — exported so `codeBlock.tsx` can resolve a
 * look without a schema round-trip, and so a test can pin the two against
 * each other. */
export function codeBlockLookValues(look: CodeBlockLook): CodeBlockLookValues {
  return LOOK_VALUES[look];
}

import { css } from "@codemirror/lang-css";
import { html } from "@codemirror/lang-html";
import { javascript } from "@codemirror/lang-javascript";
import { json } from "@codemirror/lang-json";
import { markdown } from "@codemirror/lang-markdown";
import { python } from "@codemirror/lang-python";
import { sql } from "@codemirror/lang-sql";
import type { Extension } from "@codemirror/state";

import type { CodeBlockLanguage } from "./codeBlock.layout";

/**
 * `CodeBlockLanguage` → the CodeMirror parser that highlights it. Kept out
 * of `codeBlock.layout.ts` so that file stays dependency-free (pure
 * numbers and names), and out of `codeBlock.tsx` so a host that only ever
 * needs the mapping can import it without React. A total Record: a
 * language added to `CODE_BLOCK_LANGUAGES` without a parser here is a
 * compile error.
 */
const LANGUAGE_EXTENSIONS: Record<CodeBlockLanguage, () => Extension> = {
  plaintext: () => [],
  python: () => python(),
  javascript: () => javascript(),
  typescript: () => javascript({ typescript: true }),
  json: () => json(),
  html: () => html(),
  css: () => css(),
  sql: () => sql(),
  markdown: () => markdown(),
};

export function codeBlockLanguageExtension(language: CodeBlockLanguage): Extension {
  return (LANGUAGE_EXTENSIONS[language] ?? LANGUAGE_EXTENSIONS.plaintext)();
}

/**
 * Semantic UNITS of a code document — the thing `flatten` paints as one row.
 *
 * Zach, 2026-09-15: "when you are doing the multiline port editor, each
 * line of code semantically should be flattened to a single line, as each
 * line is associated with one port ... in the expanded view you may have a
 * large multiline default value, but in this view it should display flat."
 * A port line is `name: Type = default`, and a default can span lines — a
 * dict literal, a call with one argument per line, a triple-quoted string.
 * What makes those ONE unit is exactly Python's own line-continuation rule:
 * a physical newline only ends a statement when every bracket is closed,
 * no triple-quoted string is open, and the line does not end in `\`. This
 * module is that rule, and nothing more — no parser, no grammar; a grammar
 * that knows better supplies its own `units` (`CodeBlockGrammar.units`).
 *
 * Pure: no React, no CodeMirror, no DOM. Offsets are UTF-16 code units into
 * `text` with `\n` line breaks (CodeMirror normalises `\r\n` on load).
 */

export interface UnitRange {
  /** Offset of the unit's first character (its first line's start). */
  from: number;
  /** Offset just past the unit's last character — the position of the
   * newline that ENDS it (or `text.length` for the last unit). */
  to: number;
}

export type UnitsFn = (text: string) => UnitRange[];

const OPENERS = new Set(["(", "[", "{"]);
const CLOSERS = new Set([")", "]", "}"]);

/**
 * Python's continuation rule, as unit ranges that PARTITION the text's
 * lines: every line belongs to exactly one unit, blank lines included (a
 * blank line at depth 0 is its own unit — it is one lane row, an empty one).
 * A run-away bracket or an unterminated triple quote simply swallows every
 * line to the end, which is what Python itself would do with it.
 */
export function pythonUnits(text: string): UnitRange[] {
  const units: UnitRange[] = [];
  let depth = 0;
  let inTriple: string | null = null; // `'''` or `"""`
  let inString: string | null = null; // `'` or `"` — never survives a newline
  let unitFrom = 0;
  let i = 0;
  const length = text.length;
  while (i < length) {
    const ch = text[i]!;
    if (inTriple) {
      if (text.startsWith(inTriple, i)) {
        inTriple = null;
        i += 3;
        continue;
      }
      if (ch === "\\") {
        i += 2;
        continue;
      }
      i += 1;
      continue;
    }
    if (inString) {
      if (ch === "\\") {
        i += 2;
        continue;
      }
      if (ch === inString) inString = null;
      else if (ch === "\n") {
        // Python would already have errored; the newline still ends the
        // line here so a typo never glues the rest of the lane together.
        inString = null;
        i -= 1; // re-read the newline as a structural one below
      }
      i += 1;
      continue;
    }
    if (ch === "#") {
      // A comment runs to the end of the line; brackets in it don't count.
      while (i < length && text[i] !== "\n") i += 1;
      continue;
    }
    if (ch === "'" || ch === '"') {
      const triple = ch.repeat(3);
      if (text.startsWith(triple, i)) {
        inTriple = triple;
        i += 3;
      } else {
        inString = ch;
        i += 1;
      }
      continue;
    }
    if (OPENERS.has(ch)) depth += 1;
    else if (CLOSERS.has(ch)) depth = Math.max(0, depth - 1);
    else if (ch === "\n") {
      const continued = depth > 0 || text[i - 1] === "\\";
      if (!continued) {
        units.push({ from: unitFrom, to: i });
        unitFrom = i + 1;
      }
    }
    i += 1;
  }
  units.push({ from: unitFrom, to: length });
  return units;
}

/** Offsets of every newline INSIDE a unit — the ones `flatten` folds. */
export function innerNewlines(text: string, units: UnitRange[]): number[] {
  const offsets: number[] = [];
  for (const unit of units) {
    for (let i = unit.from; i < unit.to; i += 1) {
      if (text.charCodeAt(i) === 10) offsets.push(i);
    }
  }
  return offsets;
}

/**
 * 1-based unit number of the unit containing `offset` — what the gutter
 * prints under `flatten` instead of the physical line number, so the rows
 * read 1, 2, 3 (Zach's default: the gutter counts units).
 */
export function unitNumberAt(units: UnitRange[], offset: number): number {
  for (let index = 0; index < units.length; index += 1) {
    const unit = units[index]!;
    if (offset >= unit.from && offset <= unit.to) return index + 1;
  }
  return units.length;
}

import { RangeSetBuilder, type Extension } from "@codemirror/state";
import { Decoration, EditorView, WidgetType, lineNumbers, type DecorationSet } from "@codemirror/view";

import { innerNewlines, pythonUnits, unitNumberAt, type UnitsFn } from "./codeBlockUnits";

/**
 * `flatten` — the display-only fold Zach approved on 2026-09-15 ("that is
 * exactly what we want ... I like how you are using the newline character,
 * that is basically how it looks anyway").
 *
 * Every physical newline INSIDE a unit (`codeBlockUnits.ts`) is replaced by
 * a small `⏎` widget, so the unit paints as one row: the source stays
 * byte-identical, undo untouched, the caret walks across the glyph, and
 * Enter inside a unit still inserts a real newline — it just shows up as
 * another `⏎` on the same row. WHY an inline REPLACE decoration and not a
 * value transform or the rendered rows: a transform lies about the source
 * (and every consumer must undo it), and a rendered row cannot hold a
 * caret. This is the same mechanism CodeMirror's own code folding uses
 * (an inline replace across a line break), which is why the joined lines
 * behave like one line for selection and cursor motion.
 *
 * Two of Zach's defaults, both here: the caret's own unit STAYS flat while
 * editing (no unfold-under-caret — the larger view is where real lines
 * live), and the gutter counts units, not physical lines.
 */
class NewlineWidget extends WidgetType {
  override eq(): boolean {
    return true;
  }
  override toDOM(): HTMLElement {
    const span = document.createElement("span");
    span.className = "bbox-code-block-newline";
    span.setAttribute("aria-hidden", "true");
    span.textContent = "⏎";
    return span;
  }
  /** Let a click on the glyph place the caret beside it, like any text. */
  override ignoreEvent(): boolean {
    return false;
  }
}

/** The fold itself: one replace decoration per inner newline. */
export function flattenDecorations(units: UnitsFn = pythonUnits): Extension {
  return EditorView.decorations.compute(["doc"], (state): DecorationSet => {
    const text = state.doc.toString();
    const builder = new RangeSetBuilder<Decoration>();
    for (const offset of innerNewlines(text, units(text))) {
      builder.add(offset, offset + 1, Decoration.replace({ widget: new NewlineWidget() }));
    }
    return builder.finish();
  });
}

/**
 * A line-number gutter that prints the UNIT number of each visible row.
 * Lines folded into a unit never get a gutter element of their own (they
 * are part of the first line's visual block), so the only numbers shown
 * are the unit starts — 1, 2, 3 — rather than 1, 5, 6.
 */
export function flattenLineNumbers(units: UnitsFn = pythonUnits): Extension {
  return lineNumbers({
    formatNumber: (lineNo, state) => {
      const line = state.doc.line(Math.min(lineNo, state.doc.lines));
      return String(unitNumberAt(units(state.doc.toString()), line.from));
    },
  });
}

import {
  Annotation,
  EditorState,
  Transaction,
  type AnnotationType,
  type Extension,
} from "@codemirror/state";

/**
 * Marks `CodeBlock`'s own imperative doc swaps (the `value`-prop sync) so
 * the change listener never echoes them back as typing. Lives here, not in
 * `codeBlock.tsx`, so `singleLineGuard` below can recognise and re-apply it
 * on a transaction it has to rebuild — annotations are not part of
 * CodeMirror's public `Transaction` surface (only `.annotation(type)` for a
 * type you already know to ask for, never an enumerable list), so the only
 * ones a filter can honestly preserve are ones it knows about by name.
 */
export const externalSync = Annotation.define<boolean>();

/**
 * The named annotations this guard knows how to detect and re-apply on a
 * transaction it has to rebuild: CodeMirror's own `Transaction.time` /
 * `userEvent` / `addToHistory` / `remote`, plus `externalSync` above.
 *
 * WHY this matters beyond bookkeeping: `userEvent` and `addToHistory` are
 * what `history()` groups undo steps by. Losing them made a rebuilt
 * transaction look like an ORDINARY edit with no origin and no history
 * opinion — inside CodeMirror's 500ms `newGroupDelay`, that merged
 * silently into whatever adjacent edit was already open. Type `P`, then
 * paste `a\nb` (copying a lane line with an empty selection is linewise
 * and carries a trailing `\n`, so this is common here): one Ctrl+Z used to
 * discard the typing AND the paste together, leaving `t: ` instead of
 * undoing the paste alone. `time` matters too — it feeds the SAME grouping
 * window, so a rebuilt transaction stamped with a fresh `Date.now()`
 * instead of the original's timestamp can drift outside the window the
 * original edit was actually inside.
 */
function knownAnnotations(tr: Transaction): Annotation<unknown>[] {
  const carried: Annotation<unknown>[] = [];
  function add<T>(type: AnnotationType<T>): void {
    const value = tr.annotation(type);
    if (value !== undefined) carried.push(type.of(value));
  }
  add(Transaction.time);
  add(Transaction.userEvent);
  add(Transaction.addToHistory);
  add(Transaction.remote);
  add(externalSync);
  return carried;
}

/** How many `\r`/`\n` characters sit in `text` before `pos` — the amount a position must shift left to land on the equivalent spot once those characters are removed. */
function newlinesBefore(text: string, pos: number): number {
  let count = 0;
  for (let i = 0; i < pos; i++) {
    const code = text.charCodeAt(i);
    if (code === 10 || code === 13) count++;
  }
  return count;
}

/**
 * A single-line `CodeBlock` must never contain a newline, by ANY path —
 * not just typed or pasted text (`EditorView.inputHandler` catches that
 * one, and stays for the tighter cursor placement it can do on a normal
 * keystroke) but also a COMMAND that inserts one directly, like
 * `defaultKeymap`'s `insertBlankLine` (reachable on Ctrl/Cmd+Enter when a
 * completion popup happens to be open and swallows the field's own exit
 * binding first). A `transactionFilter` sees every transaction regardless
 * of what produced it, so this is the actual guarantee, not a best effort
 * at the input layer.
 *
 * Things earlier passes at this got wrong, all fixed here:
 *
 * - The caret was clamped to the CLEANED text's length instead of shifted
 *   by how many stripped characters sat ahead of it.
 * - The replacement spec silently dropped every annotation and effect —
 *   `externalSync` (an external value-sync misread as typing) and, worse,
 *   CodeMirror's OWN `userEvent`/`addToHistory`/`time` (undo-grouping
 *   corruption — see `knownAnnotations`'s doc). `effects` are forwarded
 *   unconditionally (a plain array on `Transaction`, unlike annotations,
 *   which have no generic enumerable list); `scrollIntoView` likewise.
 * - A transaction that, once cleaned, changes the DOCUMENT not at all
 *   (pasting a bare `"\n"`, or pasting text that survives cleaning back to
 *   exactly what a replaced selection already said) either dispatched a
 *   pointless full document-replace (a dead undo step) or, at the other
 *   extreme, dropped the transaction so completely that a REPLACED
 *   SELECTION was left standing open instead of collapsed to where the
 *   paste actually ended — the very next keystroke would have overwritten
 *   the pasted text a second time. Both are handled by always computing
 *   the corrected selection and only including `changes` when the doc
 *   actually differs.
 */
export function singleLineGuard(isMultiline: () => boolean): Extension {
  return EditorState.transactionFilter.of((tr) => {
    if (isMultiline() || !tr.docChanged) return tr;
    const text = tr.newDoc.toString();
    if (!/[\r\n]/.test(text)) return tr;
    const cleaned = text.replace(/[\r\n]+/g, "");
    const { anchor, head } = tr.newSelection.main;
    const shift = (pos: number) => Math.max(0, Math.min(pos - newlinesBefore(text, pos), cleaned.length));
    const selection = { anchor: shift(anchor), head: shift(head) };
    const preserved = {
      effects: tr.effects,
      annotations: knownAnnotations(tr),
      scrollIntoView: tr.scrollIntoView,
    };
    if (cleaned === tr.startState.doc.toString()) {
      // Nothing textual changes, but the selection still has to land where
      // a real edit would have — a paste that replaced a selection with
      // (once cleaned) the same text it already held must still collapse
      // the selection to the end of the paste, not leave the old range
      // standing open for the next keystroke to clobber.
      return { selection, ...preserved };
    }
    return {
      changes: { from: 0, to: tr.startState.doc.length, insert: cleaned },
      selection,
      ...preserved,
    };
  });
}

"use client";

import { useState, type MouseEvent as ReactMouseEvent } from "react";

import { caretOffsetFromPoint } from "./caretGeometry";
import type { CodeBlockLine, CodeBlockReference } from "./codeGrammar";

/** Sum of a row's own segment text — its rendered line, stitched back together. */
function rowText(line: CodeBlockLine): string {
  return line.segments.map((segment) => segment.text).join("");
}

/**
 * A row's identity for expansion/React-key purposes: its line index PLUS
 * its own name segment, `${line}:${name}` — the donor's own scheme
 * (`typeAttributes.ts`'s `id: \`${line}:${match[1]}\``). WHY not the line
 * index alone (round 2's finding): inserting a line above shifts every
 * later index down by one, so a path keyed on the index alone silently
 * reassigns "expanded" to whatever row now happens to sit at that number
 * — expand only `target`, insert a line above it, and `origin` (now at
 * `target`'s old index) opens while `target` (now one index further down)
 * closes. Keying on the pair means an index shift changes the key, so the
 * row that moved simply drops out of `expandedPaths` (closes) instead of
 * a DIFFERENT row silently inheriting its open state — closing on an
 * unrelated edit is an acceptable rough edge; reassigning to the wrong
 * row is not. Falls back to the row's full text when no segment is
 * marked `role: "name"` (a grammar with no name concept at all).
 */
export function rowIdentity(line: CodeBlockLine): string {
  const name = line.segments.find((segment) => segment.role === "name")?.text ?? rowText(line);
  return `${line.line}:${name}`;
}

/**
 * Drops any `expandedPaths` entry whose TOP-LEVEL `line:name` no longer
 * appears among the current top-level `lines` — an edit that deletes an
 * expanded row (not just shifts it, `rowIdentity`'s own job) would
 * otherwise leave that key sitting there forever. `CodeBlock` calls this
 * on every `lines()` recompute.
 *
 * WHY this is a narrowing, not a full fix: a stale key can still
 * coincidentally match a DIFFERENT row that lands on the exact same line
 * index under the exact same name (insert `origin: int` above an expanded
 * `origin: Pose` — the new row at line 0 is ALSO named "origin", so the
 * stale `"0:origin"` key remains "valid" for it even though it belongs to
 * a row nobody ever expanded). Resolving that needs a stable identity per
 * row that survives edits, which this line-oriented, reparsed-on-every-
 * keystroke design does not carry — the donor's own `${line}:${name}`
 * scheme has the identical limitation.
 */
export function pruneExpandedPaths(
  expandedPaths: ReadonlySet<string>,
  lines: readonly CodeBlockLine[],
): ReadonlySet<string> {
  const currentTopLevel = new Set(lines.map(rowIdentity));
  let changed = false;
  const next = new Set<string>();
  for (const path of expandedPaths) {
    if (currentTopLevel.has(path.split("/")[0]!)) next.add(path);
    else changed = true;
  }
  return changed ? next : expandedPaths;
}

export interface CodeBlockRowsProps {
  /** `grammar.lines(value)` — the top-level rows. */
  lines: CodeBlockLine[];
  resolveReference?(name: string): CodeBlockReference | null;
  /**
   * A row (or the blank space below the last one) was clicked. `line` is
   * the row's own line INDEX and `column` an approximate offset within it
   * (`caretOffsetFromPoint` against the row's rendered spans — exact when
   * a row's segments concatenate back to its raw source spacing,
   * approximate otherwise). `owner` is `undefined` for a top-level row —
   * `line`/`column` are then straight into this field's own `value`,
   * compose with `lineStartOffset` for a flat offset. For a row that came
   * from a reference's `expandLines()`, `owner` carries THAT reference's
   * own owner token (`CodeBlockReference.owner`, defaulting to the
   * resolved segment's text) — `line`/`column` are into THAT source, not
   * this field's, and the host must resolve `owner` to open its source
   * (the donor's rule: a foreign row jumps to its real owner, never opens
   * this field's own document at an unrelated line).
   */
  onOpenSource?(line: number, column: number, owner?: unknown): void;
  /**
   * Which rows are expanded, keyed by path (`"3"`, `"3/1"`, …). Controlled
   * — pass this alongside `onToggleExpanded` to keep expansion state alive
   * across whatever remounts `CodeBlockRows` (`CodeBlock` does this across
   * its own `mode` toggle: `CodeBlockRows` itself unmounts every trip
   * through Source, so state living only here reset on every round trip —
   * the donor's `TypeBabbleV1` lifts this same state for the same reason).
   * Omit both to manage it internally instead (an uncontrolled default,
   * fine for a caller that never round-trips through another mode).
   */
  expandedPaths?: ReadonlySet<string>;
  onToggleExpanded?(path: string): void;
  className?: string;
  testId?: string;
}

/**
 * The RENDERED half of `CodeBlock`'s `mode` toggle: `grammar.lines()` painted
 * as bold-name / accent-type / muted-value rows, a reference segment as an
 * underlined link, and a chevron for a reference that can expand in place —
 * the "code block overlay" idea: rendered by default, source only under the
 * caret. `CodeBlock` mounts this in place of CodeMirror while `mode ===
 * "rendered"`; it never runs alongside the live document.
 */
export function CodeBlockRows({
  lines,
  resolveReference,
  onOpenSource,
  expandedPaths,
  onToggleExpanded,
  className,
  testId,
}: CodeBlockRowsProps) {
  const [uncontrolledExpanded, setUncontrolledExpanded] = useState<ReadonlySet<string>>(() => new Set());
  const expanded = expandedPaths ?? uncontrolledExpanded;
  const toggle =
    onToggleExpanded ??
    ((path: string) =>
      setUncontrolledExpanded((current) => {
        const next = new Set(current);
        if (next.has(path)) next.delete(path);
        else next.add(path);
        return next;
      }));

  const last = lines[lines.length - 1];
  return (
    <div
      data-slot="code-block-rows"
      className={`bbox-code-block-rows${className ? ` ${className}` : ""}`}
      data-testid={testId}
      // A click that reaches this container (not caught by a row, a
      // chevron, or a reference link on the way) landed on genuinely empty
      // space below the last row. There is no more specific position than
      // "the end of the last line."
      onClick={(event) => {
        if (event.target !== event.currentTarget || !onOpenSource || !last) return;
        onOpenSource(last.line, rowText(last).length);
      }}
    >
      {lines.map((line) => (
        <CodeBlockRow
          key={rowIdentity(line)}
          line={line}
          path={rowIdentity(line)}
          owner={undefined}
          resolveReference={resolveReference}
          onOpenSource={onOpenSource}
          expandedPaths={expanded}
          togglePath={toggle}
        />
      ))}
    </div>
  );
}

function CodeBlockRow({
  line,
  path,
  owner,
  resolveReference,
  onOpenSource,
  expandedPaths,
  togglePath,
}: {
  line: CodeBlockLine;
  path: string;
  /** The owner of THIS row's own source — `undefined` at the top level, the enclosing reference's owner once nested inside its `expandLines()`. */
  owner: unknown;
  resolveReference?(name: string): CodeBlockReference | null;
  onOpenSource?(line: number, column: number, owner?: unknown): void;
  expandedPaths: ReadonlySet<string>;
  togglePath(path: string): void;
}) {
  const referenceIndex = line.segments.findIndex((segment) => segment.isReference);
  const resolved = referenceIndex >= 0 && resolveReference
    ? resolveReference(line.segments[referenceIndex]!.text)
    : null;
  const expandable = Boolean(resolved?.expandLines);
  const isOpen = expandable && expandedPaths.has(path);

  const activateRow = (event: ReactMouseEvent<HTMLElement>) => {
    if (!onOpenSource) return;
    const column = caretOffsetFromPoint(event.currentTarget, event.clientX, event.clientY);
    onOpenSource(line.line, Math.min(column, rowText(line).length), owner);
  };

  const children = isOpen && resolved?.expandLines ? resolved.expandLines() : null;
  // The owner every row inside THIS reference's expansion carries: the
  // reference's own declared token, or (the common case — `expandLines`
  // alone is enough to mark rows as foreign) the resolved segment's text.
  const childOwner = resolved ? resolved.owner ?? line.segments[referenceIndex]!.text : owner;

  return (
    <div className="bbox-code-block-row" data-slot="code-block-row" data-depth={path.split("/").length - 1}>
      <span className="bbox-code-block-row-content" onClick={activateRow}>
        <span
          aria-hidden={expandable ? undefined : true}
          className="bbox-code-block-chevron"
          data-caret-ignore=""
          data-open={isOpen || undefined}
          role={expandable ? "button" : undefined}
          tabIndex={expandable ? 0 : undefined}
          onPointerDown={expandable ? (event) => event.stopPropagation() : undefined}
          onClick={expandable ? (event) => { event.stopPropagation(); togglePath(path); } : undefined}
        >
          {expandable ? (isOpen ? "▾" : "▸") : null}
        </span>
        {line.segments.map((segment, index) => {
          const isResolvedReference = index === referenceIndex && resolved;
          const className = `bbox-code-seg${segment.role ? ` bbox-code-seg--${segment.role}` : ""}${
            isResolvedReference ? ` bbox-code-ref bbox-code-ref--${resolved.kind}` : ""
          }`;
          if (isResolvedReference && resolved.onJump) {
            return (
              <span
                key={index}
                className={className}
                role="button"
                tabIndex={0}
                onPointerDown={(event) => event.stopPropagation()}
                onClick={(event) => { event.stopPropagation(); resolved.onJump!(); }}
                onKeyDown={(event) => {
                  if (event.key !== "Enter" && event.key !== " ") return;
                  event.preventDefault();
                  event.stopPropagation();
                  resolved.onJump!();
                }}
              >
                {segment.text}
              </span>
            );
          }
          return (
            <span key={index} className={className}>
              {segment.text}
            </span>
          );
        })}
      </span>
      {isOpen && children ? (
        <div className="bbox-code-block-preview">
          {children.map((child) => (
            <CodeBlockRow
              key={rowIdentity(child)}
              line={child}
              path={`${path}/${rowIdentity(child)}`}
              owner={childOwner}
              resolveReference={resolveReference}
              onOpenSource={onOpenSource}
              expandedPaths={expandedPaths}
              togglePath={togglePath}
            />
          ))}
        </div>
      ) : null}
    </div>
  );
}

import {
  autocompletion,
  type CompletionContext,
  type CompletionResult,
} from "@codemirror/autocomplete";
import { RangeSetBuilder, StateEffect, StateField, type Extension } from "@codemirror/state";
import type { UnitsFn } from "./codeBlockUnits";
import {
  Decoration,
  EditorView,
  ViewPlugin,
  WidgetType,
  type DecorationSet,
} from "@codemirror/view";

/** Which named region the caret sits in, and the text CodeMirror would replace on completion. */
export interface CodeBlockSlotAt {
  slot: string;
  start: number;
  end: number;
  query: string;
}

/** One highlighted span, expressed as a CSS class rather than a CodeMirror type. */
export interface CodeBlockDecorationRange {
  from: number;
  to: number;
  className: string;
}

export interface CodeBlockCompletion {
  label: string;
  detail?: string;
  /** CodeMirror's completion `type` — drives the built-in icon set, purely cosmetic. */
  type?: string;
}

export interface CodeBlockCompletionContext {
  text: string;
  pos: number;
  explicit: boolean;
}

export interface CodeBlockCompletionResult {
  /** Where the accepted completion starts replacing text. */
  from: number;
  /** Defaults to the caret. */
  to?: number;
  options: CodeBlockCompletion[];
}

/** One role-tagged run of text within a rendered row — a name, a type, a bit of punctuation. */
export interface CodeBlockSegment {
  text: string;
  /** A CSS-class hook (e.g. `"name"` → `.bbox-code-seg--name`); omit for unstyled text. */
  role?: string;
  /**
   * This segment names something `grammar.resolveReference` can look up.
   * The renderer asks only for segments actually on screen — resolution
   * never runs during `lines()` itself, so a grammar's parse stays cheap
   * even when resolution means a board-wide scan.
   */
  isReference?: boolean;
}

/** One row of the RENDERED-mode tree — `grammar.lines`' unit of output. */
export interface CodeBlockLine {
  /** 0-based index into the SOURCE this line came from — the field's own `value` for a top-level row, or the reference's own text for a row from `expandLines()`. This is what a `CodeBlockRows` click reports as `onOpenSource`'s `line` argument. */
  line: number;
  /**
   * Absolute character offset of the line's own start, within that SAME
   * source. NOT what `onOpenSource` reports (it reports `line`, the index,
   * so the host can place it against whichever source `owner` names) —
   * this is metadata on the row itself, e.g. for a grammar that wants to
   * report offsets without re-deriving them from `line` and the source text.
   */
  lineStart: number;
  /** Nesting depth. 0 for every row `lines()` returns directly; a reference's `expandLines()` returns its own rows at `parentDepth + 1`, applied by the renderer, not stamped here. */
  indent: number;
  segments: CodeBlockSegment[];
}

/** What a reference segment resolves to: a click target, and/or more rows to show in place. */
export interface CodeBlockReference {
  /** A grammar-defined vocabulary word (e.g. `"known"` / `"unknown"` / `"primitive"`) — a styling and behaviour hook, not interpreted by the field itself. */
  kind: string;
  /** Present when clicking the reference should navigate elsewhere instead of (or in addition to) expanding. */
  onJump?(): void;
  /**
   * Present when this reference can expand in place — e.g. a record type's
   * own fields, one level deeper. Called lazily, only while the row is
   * open, and only re-called when the row is toggled shut and open again —
   * so an expensive lookup (a live board scan) runs once per look, not
   * once per keystroke anywhere on the field.
   */
  expandLines?(): CodeBlockLine[] | null;
  /**
   * Identifies this reference as the owner of every row `expandLines()`
   * returns — an opaque token the grammar defines (a block id, a type
   * name, anything `onOpenSource`'s caller can recognise). A row inside an
   * expansion is NOT part of the field's own document — it's a preview of
   * something else's — so clicking one must report that it belongs to a
   * different source, not silently misapply its line number against the
   * top-level `value` (the donor's rule: a foreign row jumps to its real
   * owner and opens SOURCE there, at that row's own line — never "this
   * field's source at some unrelated line").
   *
   * Defaults to the resolved segment's own text (e.g. `"Pose"`) when
   * omitted, so `expandLines` alone is already enough to mark its rows as
   * foreign; set this explicitly for a richer token (an actual block
   * reference) a host can act on directly.
   */
  owner?: unknown;
}

/**
 * What makes a `CodeBlock` know its grammar. Every hook is optional — the
 * empty grammar `{}` is the plain code text box: a real CodeMirror document,
 * no slots, no completions, no marks. `slotAt` is the one function this
 * whole design rests on: a port line, a `Name = expr` alias, a nested
 * attribute tree are each a new `slotAt` plus a `decorate`/`complete` pair,
 * never a new editor.
 *
 * WHY a declarative object instead of a raw CodeMirror `Extension[]` (what
 * the field this was extracted from originally took): a grammar author
 * should not have to learn `RangeSetBuilder`, `StateField` and the
 * `autocompletion` API just to say "these are my three roles, this is what
 * completes after a colon". `grammarExtensions` below is the one place that
 * translation happens; a grammar that genuinely needs raw CodeMirror machinery
 * (a `StateField`, a widget) can still pass it through `CodeBlockGrammar.language`
 * alongside these hooks — `language` is any `Extension`, not just a lezer parser.
 */
export interface CodeBlockGrammar {
  /** A CodeMirror language/parser extension (e.g. `python()`), or any other raw extension the grammar needs mounted. */
  language?: Extension;
  /** Which slot the caret sits in. Drives `complete`; also useful to a host that wants to know what's under the cursor. */
  slotAt?(text: string, caret: number): CodeBlockSlotAt | null;
  /** Marks to paint over the raw text, recomputed on every document change. */
  decorate?(text: string): CodeBlockDecorationRange[];
  /**
   * One completion source, dispatched by slot. Return `null` (or an empty
   * `options` list) to offer nothing — that is the grammar's call, not the
   * field's: `signatureGrammar` refuses to complete the `name` slot so a
   * free-text label is never interrupted while it is typed.
   */
  complete?(
    slot: CodeBlockSlotAt | null,
    query: string,
    ctx: CodeBlockCompletionContext,
  ): CodeBlockCompletionResult | null;
  /**
   * Live-preview style folding for a lane: a line the caret is NOT on shows
   * at most this many characters, then an ellipsis; the caret's own line
   * always shows in full, and moving onto a folded line unfolds it (the
   * decoration recomputes from the selection). Omit for no folding. Has no
   * visible effect on a single-line field — there is only ever one line,
   * and it always holds the caret.
   */
  foldInactiveLinesAfter?: number;
  /**
   * The RENDERED-mode tree: the source parsed into rows of role-tagged
   * segments (bold name, accent type, muted default…), the "code block
   * overlay" — rendered by default, source only under the caret. Required
   * for `CodeBlock`'s `mode="rendered"`; a grammar that has no rendered
   * view (the plain code text box) simply omits it, and `mode` has nothing
   * to switch to.
   *
   * Nesting is a grammar concern, not a component one: `lines()` itself
   * only ever returns flat, `indent: 0` rows for the source's own lines —
   * a row that names a known reference nests DEEPER rows by resolving it
   * (`resolveReference(name).expandLines()`), not by the source text's own
   * indentation. That is what lets an attribute tree, a flat port lane and
   * a self-referencing type all share one renderer.
   */
  lines?(text: string): CodeBlockLine[];
  /**
   * What a segment marked `isReference` resolves to. Omit to render every
   * reference as plain text with no click target — the grammar's call, not
   * a default the field guesses at (a "known" judgement usually means a
   * live scan of something outside the field, e.g. a host's own registry).
   */
  resolveReference?(name: string): CodeBlockReference | null;
  /**
   * A short label for the completion badge/pill shown beside an option
   * whose `type` (`CodeBlockCompletion.type`) matches — the kind-pill
   * pattern from the grammar this was extracted from. Return `null`/
   * `undefined` for a type with no badge.
   */
  completionBadge?(type: string): string | null | undefined;
  /**
   * The document's semantic UNITS — what `flatten` paints as one row each
   * (`codeBlockFlatten.ts`). A port lane's grammar knows a unit is one
   * port; omit it and the block falls back to Python's own continuation
   * rule (`codeBlockUnits.ts`'s `pythonUnits`: brackets, triple quotes,
   * trailing backslash), which is what makes a multi-line default value
   * part of its port's line rather than lines of its own.
   */
  units?: UnitsFn;
}

function decorationExtension(decorate: NonNullable<CodeBlockGrammar["decorate"]>): Extension {
  return EditorView.decorations.compute(["doc"], (state) => {
    const ranges = decorate(state.doc.toString())
      .filter((range) => range.to > range.from)
      .slice()
      .sort((a, b) => a.from - b.from || a.to - b.to);
    const builder = new RangeSetBuilder<Decoration>();
    for (const range of ranges) {
      builder.add(range.from, range.to, Decoration.mark({ class: range.className }));
    }
    return builder.finish();
  });
}

function completionExtension(grammar: CodeBlockGrammar): Extension {
  const complete = grammar.complete!;
  const slotAt = grammar.slotAt;
  const source = (context: CompletionContext): CompletionResult | null => {
    const text = context.state.doc.toString();
    const slot = slotAt ? slotAt(text, context.pos) : null;
    const result = complete(slot, slot?.query ?? "", {
      text,
      pos: context.pos,
      explicit: context.explicit,
    });
    if (!result || result.options.length === 0) return null;
    return {
      from: result.from,
      to: result.to ?? context.pos,
      options: result.options.map((option) => ({
        label: option.label,
        detail: option.detail,
        type: option.type,
      })),
    };
  };
  // WHY `tooltipClass` is set unconditionally (not only when a badge is
  // configured): `.bbox-code-completion` is the class `codeBlock.css`'s
  // z-index rule targets. Without it every plain CodeBlock (no
  // `completionBadge`) got a popup with only CodeMirror's own default
  // classes — the bare `.cm-tooltip` selector round 1 shipped never had
  // enough specificity to beat CodeMirror's base theme rule either way,
  // but this is what makes the round-2 fix apply to EVERY completion
  // popup, not only the ones with a kind pill.
  const badge = grammar.completionBadge;
  return autocompletion({
    override: [source],
    icons: false,
    tooltipClass: () => "bbox-code-completion",
    ...(badge && {
      addToOptions: [
        {
          position: 20,
          render: (completion) => {
            const label = completion.type ? badge(completion.type) : null;
            if (!label) return null;
            const pill = document.createElement("span");
            pill.className = "bbox-code-completion-pill";
            pill.dataset.kind = completion.type;
            pill.textContent = label;
            return pill;
          },
        },
      ],
    }),
  });
}

class CodeBlockEllipsisWidget extends WidgetType {
  override eq(): boolean {
    return true;
  }
  override toDOM(): HTMLElement {
    const span = document.createElement("span");
    span.className = "bbox-code-block-ellipsis";
    span.textContent = "…";
    return span;
  }
  override ignoreEvent(): boolean {
    return false;
  }
}

/**
 * The UTF-16 offset `maxCodePoints` *code points* into `text` — never
 * inside a surrogate pair. `for...of` (and the spread below) iterates by
 * code point, so a two-unit character (most emoji) always counts as one
 * and is never split; a naive `text.slice(0, maxChars)` on code UNITS can
 * land between a high and low surrogate, leaving a lone unpaired
 * surrogate on screen (renders as a replacement glyph, sometimes worse).
 */
function codePointOffset(text: string, maxCodePoints: number): number {
  let count = 0;
  let offset = 0;
  for (const char of text) {
    if (count >= maxCodePoints) break;
    offset += char.length;
    count += 1;
  }
  return offset;
}

/**
 * Live-preview folding: every line the caret is NOT on shows at most
 * `maxChars` code points, then an ellipsis; the caret's own line always
 * shows in full, and moving onto a folded line unfolds it (the decoration
 * recomputes from the selection). Exported because `CodeBlock`'s
 * `overflow="grow-truncated"` mounts the same fold with `columns` as its
 * width — a grammar's `foldInactiveLinesAfter` and that mode are one
 * mechanism, not two.
 */
export function foldInactiveLines(maxChars: number): Extension {
  return [
    foldFocusField,
    foldFocusTracker,
    EditorView.decorations.compute(["doc", "selection", foldFocusField], (state): DecorationSet => {
      const builder = new RangeSetBuilder<Decoration>();
      const active = new Set<number>();
      // WHY the caret only counts while the document is FOCUSED (Zach,
      // 2026-09-15: "truthfully display a full line, but only when the
      // cursor is on that line, otherwise it can display more compactly"):
      // a document always has a selection — a fresh one sits at offset 0 —
      // so without the focus gate line 1 of every resting block showed in
      // full, which is not "the cursor is on that line", it is "nobody has
      // touched this yet". At rest every long line folds.
      if (state.field(foldFocusField)) {
        for (const range of state.selection.ranges) {
          active.add(state.doc.lineAt(range.head).number);
          active.add(state.doc.lineAt(range.anchor).number);
        }
      }
      for (let number = 1; number <= state.doc.lines; number += 1) {
        const line = state.doc.line(number);
        if (active.has(number) || [...line.text].length <= maxChars) continue;
        builder.add(
          line.from + codePointOffset(line.text, maxChars),
          line.to,
          Decoration.replace({ widget: new CodeBlockEllipsisWidget() }),
        );
      }
      return builder.finish();
    }),
  ];
}

/**
 * Whether the view holding this state has focus — mirrored INTO the state
 * (a `StateField`) so `foldInactiveLines`'s decorations can depend on it:
 * `decorations.compute` only recomputes on the state facets it names, and
 * focus is not state. Exported so a test (no DOM, no view) can flip it.
 */
export const setFoldFocus = StateEffect.define<boolean>();
export const foldFocusField = StateField.define<boolean>({
  create: () => false,
  update: (value, transaction) => {
    for (const effect of transaction.effects) if (effect.is(setFoldFocus)) return effect.value;
    return value;
  },
});

/** The bridge from the live view's focus to `foldFocusField`. Dispatching
 * inside `update()` is forbidden, hence the microtask; a destroyed view is
 * skipped rather than dispatched into. */
const foldFocusTracker = ViewPlugin.define((view) => {
  let alive = true;
  const sync = () => {
    queueMicrotask(() => {
      if (!alive) return;
      if (view.state.field(foldFocusField, false) === view.hasFocus) return;
      view.dispatch({ effects: setFoldFocus.of(view.hasFocus) });
    });
  };
  if (view.hasFocus) sync();
  return {
    update(update) {
      if (update.focusChanged) sync();
    },
    destroy() {
      alive = false;
    },
  };
});

/** Translates a declarative `CodeBlockGrammar` into the CodeMirror extensions `CodeBlock` mounts. */
export function grammarExtensions(grammar: CodeBlockGrammar): Extension[] {
  const extensions: Extension[] = [];
  if (grammar.language) extensions.push(grammar.language);
  if (grammar.decorate) extensions.push(decorationExtension(grammar.decorate));
  if (grammar.complete) extensions.push(completionExtension(grammar));
  if (grammar.foldInactiveLinesAfter != null) {
    extensions.push(foldInactiveLines(grammar.foldInactiveLinesAfter));
  }
  return extensions;
}

/**
 * The live-commit contract `CodeBlock` follows.
 *
 * WHY a gesture object instead of "call `onWrite` on change, `onEditEnd` on
 * blur": a text field's edit is a *gesture* with three boundaries — it
 * begins, it produces values, and it ends exactly once — and how the field
 * was left (blur, Enter, Escape, the host unmounting the panel) only
 * decides *when* the gesture ends, never *whether* the value survives. The
 * browser will not tell you about the last one: no `blur` fires for a
 * focused element removed from the DOM, so a naive commit-on-blur field
 * silently drops whatever was typed the instant its panel unmounts. This
 * class is driven from the React lifecycle instead (`CodeBlock`'s unmount
 * effect calls `commit()`), where that boundary is observable.
 *
 * Two write policies, both loss-free:
 *
 * - `live` — every keystroke writes straight into the caller's store, so
 *   the store is the only copy of the text and there is nothing left to
 *   lose. `CodeBlock` uses this exclusively (see WHY below).
 * - `exit` — the value is buffered and written once, at the end boundary,
 *   for a write that is genuinely expensive. Still loss-free, because
 *   unmount is itself an end boundary.
 *
 * `begin` fires lazily, on the first keystroke that actually changes the
 * value, so a field that was merely focused leaves no trace in undo
 * history. `end` is the commit boundary a caller can hang a semantic
 * "rename" or a debounced round trip off, without the live write ever
 * having to wait for it.
 */

export type FieldCommitMode = "live" | "exit";

export interface FieldGestureHooks {
  /** Write the value. Per keystroke in `live`, once at the end in `exit`. */
  write(value: string): void;
  /**
   * Open one undoable step. Called lazily — on the first keystroke that
   * really changes the value — so merely focusing a field leaves no trace.
   */
  begin?(): void;
  /** The commit boundary. Fires exactly once per gesture, whatever ended it. */
  end?(value: string, startValue: string): void;
}

export class FieldGesture {
  mode: FieldCommitMode;

  private readonly hooks: FieldGestureHooks;
  private editing = false;
  private began = false;
  private start = "";
  private current = "";

  constructor(hooks: FieldGestureHooks, mode: FieldCommitMode = "live") {
    this.hooks = hooks;
    this.mode = mode;
  }

  get isEditing(): boolean {
    return this.editing;
  }

  get startValue(): string {
    return this.start;
  }

  get value(): string {
    return this.current;
  }

  /** Enter the field. Idempotent: re-entering keeps the original pre-edit value. */
  focus(value: string): void {
    if (this.editing) return;
    this.editing = true;
    this.began = false;
    this.start = value;
    this.current = value;
  }

  /** One keystroke, paste, or IME commit. */
  change(value: string): void {
    if (!this.editing) this.focus(this.current);
    if (value === this.current) return;
    this.current = value;
    if (this.mode !== "live") return;
    this.ensureBegun();
    this.hooks.write(value);
  }

  /**
   * End the gesture and keep the value. Every exit route calls this — blur,
   * Enter, Escape, and the unmount cleanup — so it must stay idempotent.
   */
  commit(): void {
    if (!this.editing) return;
    if (this.mode === "exit" && this.current !== this.start) {
      this.ensureBegun();
      this.hooks.write(this.current);
    }
    const value = this.current;
    const start = this.start;
    this.editing = false;
    this.began = false;
    this.hooks.end?.(value, start);
  }

  /**
   * End the gesture WITHOUT firing `end` — for a host that owns the editing
   * session and has already decided what the final value is. WHY this
   * exists beside `commit()`: a host that ends its session on Escape first
   * restores the pre-edit value through its own store, then flips the
   * block's `editing` off. If the block committed on that transition, `end`
   * would report the document's LAST TYPED text (the store's restore never
   * reached a focused document — `CodeBlock`'s resync deliberately leaves a
   * focused, mid-gesture document alone), and the host would write the
   * cancelled text straight back over its own restore. In `live` mode
   * nothing is lost by abandoning: every keystroke already went through
   * `write`. In `exit` mode the buffered value is dropped on purpose — an
   * abandoned exit-mode gesture is a cancel.
   */
  abandon(): void {
    this.editing = false;
    this.began = false;
    this.current = this.start;
  }

  private ensureBegun(): void {
    if (this.began) return;
    this.began = true;
    this.hooks.begin?.();
  }
}

/**
 * Grammar-agnostic text-geometry helpers for the "click a rendered row and
 * land in source mode with the caret already there" gesture — the seam
 * `CodeBlock`'s `mode="rendered"` rows use to compute what `onOpenSource`
 * reports. Pure DOM; no grammar, no host.
 */

/** Absolute character offset of the start of `lineIndex` within `source`. */
export function lineStartOffset(source: string, lineIndex: number): number {
  const lines = source.replace(/\r\n?/g, "\n").split("\n");
  let offset = 0;
  for (let i = 0; i < lineIndex && i < lines.length; i++) offset += lines[i].length + 1;
  return offset;
}

/**
 * How far into `container`'s own text a click at (clientX, clientY) landed —
 * used to map a pixel click on a *rendered* row (built from separate name /
 * punctuation / type spans, not the raw source) back onto an approximate
 * column in that row's raw source line. Exact for the common case where the
 * row was authored with the same single-space `name: type = value` spacing
 * the read view renders; if punctuation was written differently, the mapped
 * column is a reasonable placement, not a guarantee.
 */
export function caretOffsetFromPoint(container: HTMLElement, clientX: number, clientY: number): number {
  const doc = document as Document & {
    caretPositionFromPoint?(x: number, y: number): { offsetNode: Node; offset: number } | null;
  };
  let node: Node | null = null;
  let nodeOffset = 0;
  if (typeof document.caretRangeFromPoint === "function") {
    const range = document.caretRangeFromPoint(clientX, clientY);
    if (range) {
      node = range.startContainer;
      nodeOffset = range.startOffset;
    }
  } else if (typeof doc.caretPositionFromPoint === "function") {
    const pos = doc.caretPositionFromPoint(clientX, clientY);
    if (pos) {
      node = pos.offsetNode;
      nodeOffset = pos.offset;
    }
  }
  if (!node || !container.contains(node)) return container.textContent?.length ?? 0;
  const walker = document.createTreeWalker(container, NodeFilter.SHOW_TEXT);
  let offset = 0;
  let current: Node | null;
  while ((current = walker.nextNode())) {
    // Chrome that shares the row but is not part of the source line — a
    // chevron glyph — is marked `data-caret-ignore`; counting it shifted
    // every mapped column one character right of the click.
    if (current.parentElement?.closest("[data-caret-ignore]")) {
      if (current === node) return offset;
      continue;
    }
    if (current === node) return offset + nodeOffset;
    offset += current.textContent?.length ?? 0;
  }
  return offset;
}
